  /* ===================================================================
     1. CONFIG — the knobs a new game changes first.
     =================================================================== */
  var CONFIG = {
    title:   "Echomaze",
    /* One short sentence, and nothing else: bounce, the dark maze, the exit.
       The stage below plays exactly that. */
    tagline: "<b class=\"w-echo\">Find</b> and aim the right way through the <b class=\"w-maze\">maze</b> to&nbsp;the&nbsp;<b class=\"w-exit\">exit</b>",
    gameSeconds: 0,                  // no clock: the run ends with the pulses

    storeUrl: {
      ios:     "https://newrare.app/#playables",
      android: "https://newrare.app/#playables",
      fallback:"https://newrare.app/#playables"
    },

    designWidth: 720, designHeight: 1280, bg: "#04060f",
    // The maze hangs below the HUD and the cannon sits above the CTA bar, so
    // nothing important ever lands under a notch or the install button.
    layout: { hudHeight: 150, ctaHeight: 112, sideMargin: 24 },
    intro: { logo: "logo", demo: "aim", caption: "" },
    hud: { score: true, timer: false },
    // The top of the frame is the maze the player is reading: a notice lands over the foot of it.
    notify: { round: "bottom" },
    /* THE BED. One track, and the menu's window of it: quiet, slower, and the
       opening of the track — the calmest stretch of it and the one thing the
       player hears before anything else. The round's five windows are on the
       BANDS below, next to the hall each of them is played in. A playable has
       no level and no menu, so it ships one window,
       a seam of pre-roll in front of it (CONFIG.music.cut). */
    /* `seam`: every window loops on the bar, two beats of crossfade ending on
       its downbeat (docs/MUSIC.md, The seam); `cut`: the playable's window,
       one seam of pre-roll into its embedded cut. */
    music: { volume: 0.10, fade: 1.8, seam: 1.14,
             cut: { from: 1.14, length: 31.997 }, menu: { from: 0, length: 36.569, rate: 0.85, gain: 0.5 } },
    copy: {
      start:"Play", ctaBar:"Install now", ctaEnd:"Play the full game",
      replay:"Replay the demo", scoreLabel:"Score", timeLabel:"Time",
      endScore:"Final score", gameOver:"Out of echoes!", timeUp:"Time's up!"
    },

    /* THE FIVE BANDS OF THE CLIMB — one per six levels, and the level map
       already names them on its own card (Warm-up, Pressure, Squeeze,
       Overdrive, Meltdown), so a band is the one turn of the game the player
       can see coming. Each carries the two things that make it a PLACE: the
       painted hall the maze hangs in, and the stretch of the track the round
       rides. They turn over together, on the same level, which is the whole
       point of putting them on one line.

       `scene` names a cut of assets/image/embed/ and the file name is the
       whole declaration — `echomaze-background-phone-blue.png` reaches
       `CONFIG.art.backgroundPhoneBlue` and `ArtImages` with it. BLUE IS FIRST
       ON PURPOSE: a playable is one round at level 0 and ships the first scene
       alone, alphabetically (tools/build/build.mjs, SCENE_SET).

       `scrim` is how far the hall is knocked back behind the maze, and it is
       measured rather than picked. This game is played in the DARK: the art
       may only ever be a texture the echo arcs read against, never something
       that competes with them. The five paintings are not equally bright —
       mean luma 26 (blue) to 47 (yellow) — so one shared scrim would leave the
       last two bands washing out the arcs that ARE the game. Each is solved
       for the same residual luma the blue hall has always had at .52, which
       leaves the COLOUR to carry the variety and not the light.

       `arc` is the ELECTRICITY of that hall: the colour a wall arcs in when a
       pulse hits it, and with it the arena's own edges, the charge gauge, the
       post-mortem scan and the glow off the floor — everything the maze is
       made of. Two colours in this game are NOT the band's and never move,
       because they are what a player reads rather than what the board looks
       like: the gate is green and the valves are gold, in all thirty levels.
       Each `arc` is picked to stay clear of both, which is measured in HUE and
       not eyeballed: the gate sits at H142 and the valves at H40, so the green
       band arcs LIME (H108, and lighter) rather than any green nearer the
       gate — a turquoise arc read as the same colour as the gate's jambs, and
       the gate is what the reveal is spent looking for. The hot bands arc a
       saturated orange and a cold lemon for the same reason, well off the
       valves' amber. The PULSE the player
       fires does not move either: it is the one object they steer, and it
       reads best as the one constant light on a board that changes.

       `music` is the window of the track (see docs/MUSIC.md). The entry points
       are the track's own seams, measured and not guessed: the opening runs to
       17 s, the body enters at 18, the arrangement cuts out entirely at 55 and
       again at 113, and the outro starts at 150.
       A band also carries the RULE that arrives with it, and that is the other
       half of the climb: the lerped knobs below (see web.levels.tune in the
       manifest) only ever make the same board bigger, darker and shorter on
       pulses, which is a ramp of PERCEPTION. One new rule a band is a ramp of
       DECISION — something else to read before the first shot, three times
       over by the top of the ladder:

         Warm-up    the board, and nothing else
         Pressure   `decoys`  — two more gates in the ceiling, and only one of
                    the three is the way out
         Squeeze    `crystal` — the gate is locked, and its key stands in the
                    bay (a ricochet) for the first half of the band, in a dead
                    end (a whole pulse) for the second
         Overdrive  `surge`   — an electric fence across the mouth row with ONE
                    gap in it, and the gap moves on a cycle the player has to
                    learn while playing
         Meltdown   all three at once

       A playable has no level, rides the first band and therefore ships the
       game as it always was: one board, six doors, one way out. */
    bands: [
      // levels   hall                         scrim   arc (the walls)   the stretch of the track          the rule that arrives
      { scene: "backgroundPhoneBlue",   scrim: 0.52, arc: "#7ef9ff", music: { from: 18,  length: 31.997 } },                                          //  1-6   Warm-up
      { scene: "backgroundPhoneGreen",  scrim: 0.70, arc: "#7cff5a", music: { from: 57,  length: 27.425 }, decoys: [1, 2] },                          //  7-12  Pressure
      { scene: "backgroundPhonePurple", scrim: 0.67, arc: "#c48cff", music: { from: 87,  length: 20.573 }, crystal: "split" },                        // 13-18  Squeeze
      { scene: "backgroundPhoneOrange", scrim: 0.63, arc: "#ff8a3c", music: { from: 114, length: 18.282 }, surge: true },                             // 19-24  Overdrive
      { scene: "backgroundPhoneYellow", scrim: 0.77, arc: "#f2ff4a", music: { from: 128, length: 18.287 }, decoys: 2, crystal: "maze", surge: true }   // 25-30  Meltdown
    ],

    /* --- the maze -------------------------------------------------------
           A 12 x 9 grid on the 672 px band: 56 x 61 cells, so the corridors are
           barely wider than the pulse and the board is a real labyrinth rather
           than a few rooms. The SIX mouths are still six, because a mouth is
           mouthW cells wide — a fine grid downstairs would give the cannon six
           slots it cannot reliably hit from the middle of the bay. */
    cols: 12,
    rows: 9,
    mouthW: 2,                       // cells per mouth: 12 / 2 = the six doors
    wallT: 14,                       // wall thickness (design px)
    gateH: 68,                       // the band above the maze holding the gate
    chamberH: 392,                   // the launch bay under the mouths: deep
                                     // enough to reach the outermost mouth in
                                     // one straight shot, without banking

    /* --- the reveal ----------------------------------------------------
           The whole board is powered up at the start — and that is the ONLY
           time any of it is drawn for free. When the grid drops, nothing is
           left on screen: not the maze, not the mouths, not even the walls of
           the arena. From then on a wall exists only where a pulse just hit
           one, and only for as long as that arc takes to die out. */
    revealSeconds: 1,                // short on purpose: one glance, not a study
    revealSkipAfter: 0.4,            // a tap before this cannot skip the reveal
    revealFade: 0.5,                 // seconds the grid takes to die out
    echoFade: 2.4,                   // seconds an arc takes to fade to nothing

    /* --- the post-mortem ------------------------------------------------
           A lost run never cuts straight to the score. The grid is slammed
           back on and the whole board is shown one last time: a scan climbs
           from the mouth row to the ceiling, powering every wall back up
           behind it, and then the corridor that WAS the way out is traced
           from its door to the gate. Being shown the answer is what makes the
           next run worth firing — and it is the one moment the player gets to
           see how close they were. */
    recapSeconds: 3,                 // the whole post-mortem, then the end screen
    recapSurge: 0.4,                 // dead beat before the power comes back
    recapSweep: 0.85,                // seconds the scan takes to climb the board
    recapTrace: 1.15,                // seconds the true corridor takes to draw

    /* --- the cannon and the pulses ------------------------------------- */
    startBalls: 6,                   // one per mouth, and the mouths close
    ballR: 8,                        // small enough for a 42 px corridor
    ballSpeed: 620,                  // px/sec, constant for a pulse's whole life
    ballLife: 11,                    // seconds of charge, then it fizzles out
    lift: 1900,                      // px/sec^2 bent into the heading: it CLIMBS
    minRatio: 0.50,                  // never flatter than 30 deg, never steeper
                                     // than 60: it always makes lateral AND
                                     // vertical progress, which is what turns a
                                     // bouncing ball into a maze runner. Tuned
                                     // on a headless sim of the real physics:
                                     // a pulse in the TRUE corridor gets out
                                     // ~75% of the time in ~5 s, and one in a
                                     // decoy never does.
    bounceJitter: 0.05,              // rad of noise per contact: no orbits
    subDiv: 4,                       // px per collision sub-step: small enough
                                     // that a pulse can never be pushed out of
                                     // a corner through the far side of a bar
    minAimDeg: 24,                   // never aim flatter than this
    aimBeam: 320,                    // long enough that the sight always reaches
                                     // the mouth row: its tip IS the door the
                                     // shot goes through, and in the dark that
                                     // is the only read the player gets
    shotCooldown: 0.22,
    cannonH: 56, muzzle: 88,

    /* --- the flaps -----------------------------------------------------
           The mouth row is six one-way valves. A pulse coming up from the bay
           pushes its flap open and slips through; the flap drops shut behind
           it, so nothing ever falls back out into the bay. It is never spent:
           the next pulse pushes the same flap open again. */
    flapTime: 0.34,                  // seconds the flap takes to drop back

    /* --- the valves ----------------------------------------------------
           A pulse that runs out of charge INSIDE the maze does not simply go
           out: it collapses into the opening it last climbed through and
           becomes a one-way valve there. So the board gets kinder as the rack
           empties — every corridor a pulse died in now pushes the next one
           upward instead of letting it drop back down, and a corridor with
           several valves in it only flows one way: toward the ceiling. */
    valveScore: 60,                  // a spent pulse still pays for its valve

    /* --- scoring ------------------------------------------------------- */
    bounceScore: 2,                  // every contact pays: bouncing IS the map
    mapScore: 30,                    // a wall struck for the first time
    depthScore: 150,                 // per row climbed inside the maze
    escapeBonus: 3500,               // the way out. With the rows a climb pays,
                                     // it is the FLOOR of an escape: 3500 plus
                                     // rows x depthScore clears 1.5x the level
                                     // objective at level 30, so finding the
                                     // gate is worth its two stars whatever the
                                     // run cost.

    /* THE RACK IS THE SCORE. A pulse left in the rack pays more than a pulse
       spent can ever farm — a whole extra run through the maze is worth a few
       hundred points in walls, bounces and rows, and the pulse it cost is
       worth `spareBonus`. So the maximum score of a board is the escape found
       with the FIRST shot, and every door tried by elimination is paid for out
       of the total. Reading the board beats working through all six. */
    spareBonus: 1500,                // per pulse left in the rack when it opens
    perfectShots: 1,                 // the cheapest an escape can possibly be
    parScore: 5000,                  // the point objective of a run with no
                                     // levels under it: what a lost run has to
                                     // have mapped to be worth its one star.
                                     // Benched on the shipped board: a rack
                                     // emptied into wrong doors scores
                                     // 5 600-6 800 over six seeds and a single
                                     // pulse scores ~2 300, so 5 000 is a rack
                                     // spent reading the maze rather than one
                                     // lucky shot. The web build uses the
                                     // gate alone (see levelTally).

    /* --- the false gates (bands 2 and 5) --------------------------------
           Two more holes in the ceiling, pierced over a DEAD corridor, lit
           exactly like the real one from the first frame to the last, and they
           are the SAME drawing at every moment of the round. The one thing
           that ever tells them apart is the beacon that goes out of the true
           one while the board is powered up — a thing that happens on it, not
           a thing the other two lack, because two gates visibly marked as
           fakes is a board with one gate on it. A pulse that climbs into a false
           one is eaten and takes the gate down with it, so a door is bought
           with a pulse: the same trade the five dead ends already are, moved
           up to the ceiling where it costs the most. */
    decoyScore: 200,                 // what the answer is worth: the pulse it
                                     // cost is worth `spareBonus`, so learning
                                     // a gate this way is still a loss

    /* --- the crystal (bands 3 and 5) ------------------------------------
           The gate is barred the moment the round starts — never during the
           reveal, which is the look the player gets at the ceiling — and the
           bar only comes off when the crystal does.
           The crystal is the one object in this game that is lit in the
           dark from start to finish — it has to be, or a locked board would be
           a board with no way out at all — and where it stands is what it
           costs:

             "bay"   in the launch bay, in the open: a pulse can shatter it and
                     carry on into a mouth, so the board is still a one-pulse
                     board for a player who plans the ricochet
             "maze"  in a dead end: one pulse for the crystal, one for the way
                     out, and `shotPar` moves to 2 so three stars still means
                     "the cheapest this board can be". It is never in the TRUE
                     corridor — a key on the way out would hand over the way
                     out. */
    crystalScore: 400,
    crystalR: 19,                    // in the bay. Inside the maze it is cut
                                     // down to the cell it stands in.

    /* --- the surge (bands 4 and 5) --------------------------------------
           An electric fence is strung along the mouth row and every door is
           shut — except ONE. The gap walks the doors on a cycle that is random
           per board and then repeats, one step a beat, and a pulse that meets
           the fence instead of the gap is destroyed on it — and takes the door
           with it. What it costs is the whole shot; what it buys is that door,
           open for the rest of the round.

           So the fence is a TIMING instrument and not a second memory test.
           The gap is lit — it has to be, or the mechanic would be a coin toss —
           and what the player has to work out is the ORDER it tours the doors
           in, because a pulse takes the better part of a beat to climb out of
           the bay: the shot is fired at the door the gap is about to reach,
           never at the one it is standing on. Nothing is shown up front and
           nothing is paused for it; the cycle turns from the moment the lights
           go out and the run is where it is learned.

           And the fence only gets one pulse per door: a door that stopped one
           has done its job and BURNS OUT — it stays open for the rest of the
           round and drops out of the tour, which keeps turning over the doors
           that are left. So a mistimed shot is paid for once and buys something
           (the door it was aimed at is now free), instead of being a toll the
           same door can charge again and again.

           The pulse dying on the wire is what keeps that honest: a pulse thrown
           BACK would rattle round the bay and take two or three more doors down
           on the ricochet, so one bad shot would open the whole fence and the
           timing would stop mattering by the second board. One pulse, one door.
           A shot that goes through the gap costs nothing and changes nothing:
           the pulse is in the maze and the cycle turns on. */
    surgePeriod: 1,                  // seconds the gap stands on a door
    surgeFlash: 0.2                  // seconds of white on the fence at each
                                     // jump: the beat, made audible to the eye
  };

  /* ===================================================================
     2. ASSETS — embedded base64 data URIs only (no network requests ever).
     Everything the game itself draws is code (the arcs, the gate, the cannon,
     the pulses), so the bytes here are the app icon, the painted void behind
     the board, one pictogram and the sound set.
     =================================================================== */
  var ASSETS = {
    images: {
      // assets/image/icon/thumb/echomaze.png (320 px cut of assets/image/icon/echomaze.png)
      "logo": "data:image/png;base64,",
      // assets/motor/lucide/chevrons-up.svg — the exit gate marker
      "icoExit": "data:image/svg+xml;base64,"
    },
    sounds: {
      // The background bed, looped and crossfaded by Music (see CONFIG.music).
      // The playable ships ONE window of the track — the first map band's, all
      // of which it can reach without a level; the web target ships the whole
      // of it instead (`web.music` in the manifest):
      //   ffmpeg -ss 16.86 -t 33.137 -i assets/audio/music/echomaze.mp3 \
      //          -ac 1 -ar 44100 -b:a 64k music.mp3
      "music": "data:audio/mpeg;base64,",
      // Every other key is a role of the house kit (`sfx` in manifest.json).
    }
  };

  /* ===================================================================
     6. GAME — ECHOMAZE.

     An electric labyrinth hangs over a launch bay. It is powered up for a
     couple of seconds at the start of the run — the ONLY time any of it is
     drawn for free — and then everything goes out: the maze, the six mouths
     along its floor, and the walls of the arena itself. Nothing is remembered
     on screen.

     From then on the board exists only where a pulse just hit it. Every contact
     ECHOES: the wall it struck, and the two walls in line with it, flare white
     and die out over a couple of seconds, so the player is echolocating a maze
     they can no longer see. A pulse also CLIMBS — a constant lift is bent into
     its heading, inside a cone that keeps it from ever going flat or straight
     up — so it works its way upward through whatever corridor it is in instead
     of diffusing about.

     One mouth of the six is the real way in; the other five open into dead ends
     (see carve()). Each mouth is a ONE-WAY FLAP: a pulse rising out of the bay
     pushes it open and slips through, and it drops shut behind so nothing ever
     falls back out — but the next pulse pushes the same flap open again, so a
     door is never spent. A pulse that reaches the ceiling gap leaves the board
     and wins the run.

     A pulse that runs out of charge is not simply lost: whatever is left of it
     COLLAPSES INTO THE OPENING IT LAST CLIMBED THROUGH and stands there as a
     one-way valve of its own (see forgeValve). Every corridor a pulse died in
     flows one way from then on, and a corridor with two or three valves stacked
     in it can no longer be fallen back down — so the board is at its cruellest
     with a full rack and kindest with the last pulse in it.

     A run that ends with an empty rack gets a POST-MORTEM before the score: the
     power comes back on, a scan climbs the board lighting every wall behind it,
     and the corridor that was the way out draws itself from its door up to the
     gate (see startRecap / drawTrueWay). The player is shown the answer, which
     is the whole reason to fire the next run.
     =================================================================== */
  var Game = (function () {
    var C = CONFIG, TAU = Math.PI * 2;

    /* --- the palette --------------------------------------------------- */
    /* The electricity of the hall being played in — the band's (CONFIG.bands),
       re-read in reset(). Every wall, edge, gauge and glow in this file is
       drawn with it, which is why it is one variable and not a parameter. */
    var ARC = CONFIG.bands[0].arc;
    var EXIT_COL = "#4ade80";                  // the gate, and only the gate
    var VALVE = "#ffc857";                     // what the player built, not the board
    var PULSE = { core: "#7ef9ff", light: "#eaffff", edge: "#0d3f6b" };
    var DYING = "#ff2d78";                     // a pulse near the end of its charge
    /* Two more colours that are a RULE and not a look, so like the gate's green
       and the valves' amber they are the same in all thirty levels. The crystal
       and the bar it holds over the gate are one object in two places and
       therefore one colour, picked clear of the gate (H142), the valves (H40)
       and the two halls it is ever seen in (purple H267, lemon H64). The surge
       borrows the danger colour the game already has: one thing on this board
       destroys a pulse and one colour says so. */
    var CRYSTAL = "#ff4fd8";
    var SURGE = DYING;

    /* --- geometry, rebuilt whenever Layout moves ----------------------- */
    // The arena is one box: the maze fills its upper part, the launch bay its
    // lower part, and the maze's ceiling doubles as the arena's ceiling.
    var field = { left: 0, right: 0, top: 0, bottom: 0 };
    var M = { cols: 0, rows: 0, cw: 0, ch: 0, x0: 0, y0: 0, y1: 0 };
    var cannon = { x: 0, y: 0 };
    var bgCv = null;

    /* The band of the climb the round is being played in — its hall, its scrim
       and its stretch of the track (CONFIG.bands). Fixed in reset() BEFORE
       geometry() runs, because the backdrop it composites is the band's. A
       playable has no level and rides the first band, which is the one scene
       it ships. */
    var BAND = C.bands[0];

    /* --- the board -----------------------------------------------------
       hSolid[r * cols + c] is the HORIZONTAL wall above cell (c, r), so r runs
       0..rows: row 0 is the ceiling (pierced once, at the exit) and row `rows`
       is the mouth row. vSolid[r * (cols + 1) + c] is the VERTICAL wall on the
       left of cell (c, r). The two outermost vertical walls are not stored as
       segments: they ARE the arena's sides, drawn and bounced as one long
       electric edge (the same fence as games/bouncetry). */
    var hSolid, vSolid, mainCell;
    var entryMouth, entryCol, exitCol, MOUTHS;
    var decoys;                     // the band's false gates: { c, dead, burn }
    var crystal;                    // the key to the gate, or null
    var lockWalls, lockFlare;       // the bar it holds over the gates
    var surgeSeq, surgeI, surgeT, surgeFlash, surgeNoise, surgeCrackle;
    var shotPar;                    // the cheapest an escape can be on THIS
                                    // board: one pulse, or two when the crystal
                                    // stands in a dead end
    var walls, hw, vw;              // every segment, plus the two lookup grids
    var wallCount;                  // solid walls, i.e. what there is to find
    var mouths;                     // one per door: { t } — 1 shut, 0 wide open

    /* --- run state ----------------------------------------------------- */
    var phase;                      // "reveal" | "play" | "recap" | "over"
    var valves;                     // the one-way valves the spent pulses left
    var balls, queue, fired, bounces, mapped, deepest, escaped, spare;
    var truePath, recapT, recapStep, recapRow;  // the post-mortem: the answer,
                                                // its clock and its scan
    var score, clock, revealT, darkT, endT, recoil, lastShot, lastWall, lastText;
    var jitterT, gateFlare;
    var aimA, aiming, zaps;

    /* --- what the band brings ------------------------------------------
       The three rules are declared on the band (CONFIG.bands) and read through
       these, so nothing below ever tests a level number. A playable rides the
       first band and gets none of them. */
    /* WHERE THE LEVEL SITS INSIDE ITS BAND, 0..1. Used by the rules that step
       up across a band rather than arriving whole. The top of the ladder is the
       edge case: `d` is exactly 1 there, so the naive fraction wraps back to 0
       and the last level of the game would play the softest setting of its own
       band. */
    function bandFrac() {
      var x = (LEVEL_D == null ? 0 : LEVEL_D) * 5;
      var i = clamp(Math.floor(x), 0, C.bands.length - 1);
      return clamp(x - i, 0, 1);
    }
    /* A band may ramp its gates instead of arriving with all of them:
       `decoys: [1, 2]` opens on one false gate and steps up to two, `decoys: 2`
       is two from its first level. Three doors on the first board of a band is
       the whole rule landing at once, and the player has nothing to compare it
       to yet.

       The step is at 0.4 of the band and not at its middle, because the map
       FORKS and its levels are not evenly spread over `d` — band 2 lands its
       six at .03 .27 .27 .49 .72 .94, so 0.4 is what splits them three and
       three and 0.5 would split them four and two. */
    function featDecoys() {
      var d = BAND.decoys;
      if (!d) return 0;
      if (typeof d === "number") return d;
      return bandFrac() < 0.4 ? d[0] : d[d.length - 1];
    }
    function featSurge() { return !!BAND.surge; }
    // "split" is the band that teaches: the ricochet in the bay over its lower
    // half, the whole extra pulse over its upper half. It is measured on the
    // same `d` the band itself comes off — the map forks, so the levels in a
    // band are not six consecutive numbers and counting them would put the
    // lesson on the wrong side of it.
    function crystalHome() {
      var h = BAND.crystal || "", d;
      if (h !== "split") return h;
      d = bandFrac();
      return d < 0.5 ? "bay" : "maze";
    }

    /* --- small canvas helper ------------------------------------------- */
    function rr(x, px, py, w, h, r) {
      var k = Math.min(r, w / 2, h / 2);
      x.beginPath();
      x.moveTo(px + k, py);
      x.lineTo(px + w - k, py); x.quadraticCurveTo(px + w, py, px + w, py + k);
      x.lineTo(px + w, py + h - k); x.quadraticCurveTo(px + w, py + h, px + w - k, py + h);
      x.lineTo(px + k, py + h); x.quadraticCurveTo(px, py + h, px, py + h - k);
      x.lineTo(px, py + k); x.quadraticCurveTo(px, py, px + k, py);
      x.closePath();
    }
    // Two hex colours blended, for the pulse fading toward its danger colour.
    function mix(a, b, t) {
      var x = parseInt(String(a).slice(1), 16), y = parseInt(String(b).slice(1), 16);
      var r = Math.round(((x >> 16) & 255) + (((y >> 16) & 255) - ((x >> 16) & 255)) * t);
      var g = Math.round(((x >> 8) & 255) + (((y >> 8) & 255) - ((x >> 8) & 255)) * t);
      var bl = Math.round((x & 255) + ((y & 255) - (x & 255)) * t);
      return "rgb(" + r + "," + g + "," + bl + ")";
    }

    /* =================================================================
       GEOMETRY
       ================================================================= */
    function geometry() {
      field.left = Layout.left;
      field.right = Layout.right;
      field.top = Layout.top + C.gateH;             // the gate band sits above
      field.bottom = Layout.bottom - 10;            // the arena floor
      M.cols = C.cols; M.rows = C.rows;
      M.x0 = field.left;
      M.cw = (field.right - field.left) / M.cols;
      M.y0 = field.top;
      M.ch = (field.bottom - C.chamberH - M.y0) / M.rows;
      M.y1 = M.y0 + M.ch * M.rows;                  // the mouth row
      cannon.x = (field.left + field.right) / 2;
      cannon.y = field.bottom - C.cannonH;
      if (walls) placeWalls();
      placeCrystal();
      buildBackdrop();
    }

    /* The void behind the maze, composited ONCE: the painted circuit hall of
       the band being played (BAND.scene, out of ArtImages), cover-fit to the
       design canvas, then knocked back by the band's own scrim — this game is
       played in the dark, so the art may only ever be a texture the echo arcs
       read against, never something that competes with them. Falls back to the
       first band's hall, then to the cold nebula gradient, so a bare frame is
       impossible whatever a build ships. */
    /* geometry() runs on every reset(), i.e. on every replay, and the
       backdrop is a full-frame canvas (~3.5 MB of pixels): rebuilt each time,
       the old one was garbage a phone reclaimed with a major GC mid-round a
       few rounds later. `bgSig` names exactly what the picture is made of —
       the frame, the Layout bands its vignette is cut at, the hall it shows
       (and whether that image has decoded yet, since ArtImages may land after
       the first build) and the band's scrim — so it is composited again only
       when one of them moves, and the canvas it replaces is freed. */
    var bgSig = "";

    function buildBackdrop() {
      var g, x, y, s, w, h;
      var key = (typeof ArtImages !== "undefined" && ArtImages[BAND.scene]) ? BAND.scene : C.bands[0].scene;
      var img = (typeof ArtImages !== "undefined" && ArtImages[key]) || null;
      var sig = view.w + "x" + view.h + "|" + Layout.top + "," + Layout.h + "," + Layout.bottom + "|" +
                key + ":" + (img && img.width ? img.width + "x" + img.height : "-") + "|" + BAND.scrim;
      if (bgCv && sig === bgSig) return;
      bgSig = sig;
      bgCv = freeCanvas(bgCv);
      bgCv = document.createElement("canvas");
      bgCv.width = view.w; bgCv.height = view.h;
      g = bgCv.getContext("2d");
      g.fillStyle = C.bg; g.fillRect(0, 0, view.w, view.h);
      if (img && img.width) {
        s = Math.max(view.w / img.width, view.h / img.height);   // cover, never stretch
        w = img.width * s; h = img.height * s;
        g.drawImage(img, (view.w - w) / 2, (view.h - h) / 2, w, h);
        g.fillStyle = rgba("#04060f", BAND.scrim);               // the band's own stop under the dark
        g.fillRect(0, 0, view.w, view.h);
      } else {
        var rad = g.createRadialGradient(view.w / 2, Layout.top + Layout.h * 0.34, 40,
                                         view.w / 2, Layout.top + Layout.h * 0.34, view.w * 0.95);
        rad.addColorStop(0, "#121c4e"); rad.addColorStop(0.5, "#0a1030"); rad.addColorStop(1, "#04060f");
        g.fillStyle = rad; g.fillRect(0, 0, view.w, view.h);
        g.fillStyle = "rgba(126,249,255,.055)";
        for (y = 18; y < view.h; y += 36) for (x = 18; x < view.w; x += 36) g.fillRect(x, y, 2, 2);
      }
      var band = g.createLinearGradient(0, 0, 0, view.h);
      band.addColorStop(0, "rgba(3,5,14,.8)");
      band.addColorStop(clamp(Layout.top / view.h, 0.02, 0.4), "rgba(3,5,14,0)");
      band.addColorStop(clamp(Layout.bottom / view.h, 0.6, 0.98), "rgba(3,5,14,0)");
      band.addColorStop(1, "rgba(3,5,14,.8)");
      g.fillStyle = band; g.fillRect(0, 0, view.w, view.h);
    }

    /* =================================================================
       THE MAZE — one true way in, five dead ends.

       1. The main path is carved bottom-up: it enters at one mouth, climbs the
          bottom row straight (so the six mouths stay six separate openings),
          then in every row above it runs sideways for a few cells and steps up
          again. It ends by piercing the ceiling: that hole is the exit.
       2. Every other mouth is opened too and sends a random walk up into the
          board, FORBIDDEN from entering a cell of the main path — which is
          what makes a decoy a genuine dead end, however long and promising it
          looks. The five walks advance one cell at a time in turn, so they
          share the space instead of the first one eating half the board, and
          they keep going until not one of them can reach a free cell. The dead
          half therefore ends up as five long winding corridors. A walk that
          stopped early used to leave the rest of that half as loose cells, and
          a loose cell is a one-cell box: the board read as a field of little
          squares instead of a labyrinth, which is what this fixes.
       3. A pocket the walks could not reach — sealed off behind the main path —
          is carved into a corridor by the same walk and then hung off a
          neighbouring dead end by a SINGLE opening, so it reads as a branch. It
          is never hung off the main path: that would be charge a pulse can
          waste in a side branch of the one corridor that leads out.

       validate() then flood-fills from each mouth and insists that exactly one
       of them reaches the exit. It has never had to reject a board, but the
       rule is the whole game, so it is checked rather than assumed.
       ================================================================= */
    function hI(r, c) { return r * M.cols + c; }
    function vI(r, c) { return r * (M.cols + 1) + c; }

    function carve() {
      var r, c, i, t, dir, run, j, n, stack, packs, live, pid, id, pocket, pack, cand;
      hSolid = []; vSolid = []; mainCell = [];
      for (i = 0; i < (M.rows + 1) * M.cols; i++) hSolid.push(1);
      for (i = 0; i < M.rows * (M.cols + 1); i++) vSolid.push(1);
      for (i = 0; i < M.rows * M.cols; i++) mainCell.push(0);

      // --- 1. the main path
      entryMouth = Rand.int(0, MOUTHS - 1);
      entryCol = mouthCol(entryMouth) + Rand.int(0, C.mouthW - 1);
      mainCell[hI(M.rows - 1, entryCol)] = 1;
      hSolid[hI(M.rows - 1, entryCol)] = 0;
      c = entryCol;
      for (r = M.rows - 2; r >= 0; r--) {
        // Just above the mouths the run is kept short, so the decoys next door
        // still have room to be more than a one-cell pocket.
        dir = Rand.chance(0.5) ? -1 : 1;
        if (c === 0) dir = 1; else if (c === M.cols - 1) dir = -1;
        run = Rand.int(0, r === M.rows - 2 ? 2 : 5);
        t = c;
        mainCell[hI(r, t)] = 1;
        for (i = 0; i < run; i++) {
          if (t + dir < 0 || t + dir >= M.cols) break;
          vSolid[vI(r, Math.max(t, t + dir))] = 0;
          t += dir;
          mainCell[hI(r, t)] = 1;
        }
        if (r > 0) hSolid[hI(r, t)] = 0;
        c = t;
      }
      exitCol = c;
      hSolid[hI(0, exitCol)] = 0;                   // the way out

      // --- 2. the six throats. A mouth is mouthW cells wide and those cells
      //        are joined into one opening.
      for (i = 0; i < MOUTHS; i++) {
        for (j = 0; j < C.mouthW; j++) hSolid[hI(M.rows, mouthCol(i) + j)] = 0;
        for (j = 1; j < C.mouthW; j++) vSolid[vI(M.rows - 1, mouthCol(i) + j)] = 0;
      }
      var dead = [];
      for (i = 0; i < M.rows * M.cols; i++) dead.push(0);
      // The whole mouth row is spoken for before anything else is carved: one
      // sideways link down there would weld two doors into a single entrance,
      // and "one true way in" is the entire game.
      for (c = 0; c < M.cols; c++) if (!mainCell[hI(M.rows - 1, c)]) dead[hI(M.rows - 1, c)] = 1;

      function free(cc, rr2) {
        return cc >= 0 && cc < M.cols && rr2 >= 0 && rr2 < M.rows &&
               !mainCell[hI(rr2, cc)] && !dead[hI(rr2, cc)];
      }
      function open(c0, r0, c1, r1) {
        if (r0 !== r1) hSolid[hI(Math.max(r0, r1), c0)] = 0;
        else vSolid[vI(r0, Math.max(c0, c1))] = 0;
      }
      function shuffle(a) {
        for (var k = a.length - 1, q, tmp; k > 0; k--) {
          q = Rand.int(0, k); tmp = a[k]; a[k] = a[q]; a[q] = tmp;
        }
        return a;
      }
      /* ONE cell of one walk. Called round-robin, so every walk gets the same
         chance at the space in front of it. Returns false once its stack has
         been unwound, i.e. once nothing it can still backtrack to touches a
         free cell — which is the only way this half of the board is left
         without loose cells in it. A cell is claimed the moment it is walked
         into, so two walks can never meet: each mouth keeps its own dead end. */
      function walk(p) {
        var top, opts, up, n;
        while (p.st.length) {
          top = p.st[p.st.length - 1];
          opts = [];
          // upward first, so opts[0] is the climb whenever there is one
          if (free(top[0], top[1] - 1)) opts.push([top[0], top[1] - 1]);
          // A walk leaves the mouth row upward only — and comes back to it
          // only by backtracking, which is why this tests the ROW and not the
          // first step: a sideways step down there would merge two mouths.
          if (top[1] < M.rows - 1) {
            if (free(top[0] - 1, top[1])) opts.push([top[0] - 1, top[1]]);
            if (free(top[0] + 1, top[1])) opts.push([top[0] + 1, top[1]]);
            if (free(top[0], top[1] + 1)) opts.push([top[0], top[1] + 1]);
          }
          if (!opts.length) { p.st.pop(); continue; }
          up = opts[0][1] === top[1] - 1;
          // biased upward, so a decoy climbs and stays tempting instead of
          // curling into a blob next to its own door
          n = (up && opts.length > 1 && Rand.chance(0.55)) ? opts[0] : opts[Rand.int(0, opts.length - 1)];
          open(top[0], top[1], n[0], n[1]);
          dead[hI(n[1], n[0])] = 1;
          if (p.cells) { p.cells.push(n); pid[hI(n[1], n[0])] = p.id; }
          p.st.push(n);
          return true;
        }
        return false;
      }

      //        Then the five decoy walks, grown in step — one cell each per
      //        turn — until the dead half of the board is all corridors.
      pid = [];
      for (i = 0; i < M.rows * M.cols; i++) pid.push(0);
      packs = [];
      for (i = 0; i < MOUTHS; i++) {
        if (i === entryMouth) continue;
        // both cells of the door are roots: a mouth may branch twice
        stack = [];
        for (j = 0; j < C.mouthW; j++) stack.push([mouthCol(i) + j, M.rows - 1]);
        packs.push({ st: shuffle(stack), cells: null, id: 0 });
      }
      shuffle(packs);                               // no mouth is always first
      do {
        live = 0;
        for (i = 0; i < packs.length; i++) if (walk(packs[i])) live++;
      } while (live);

      // --- 3. the pockets the walks could not reach
      id = 0;
      for (r = 0; r < M.rows; r++) for (c = 0; c < M.cols; c++) {
        if (mainCell[hI(r, c)] || dead[hI(r, c)]) continue;
        id++;
        pocket = [[c, r]];
        dead[hI(r, c)] = 1; pid[hI(r, c)] = id;
        pack = { st: [[c, r]], cells: pocket, id: id };
        while (walk(pack)) { /* carve the whole pocket into one corridor */ }
        // Then a SINGLE door, onto any dead end that touches it. One door can
        // only graft the pocket onto one existing corridor, never weld two of
        // them together, so no decoy can inherit the way out this way. The main
        // path is left out on purpose: a branch hanging off the TRUE corridor
        // is charge a pulse can waste in it, and the odds of getting a pulse up
        // that corridor is what the whole run is tuned around. A pocket walled
        // in by the main path alone therefore stays sealed — no pulse can reach
        // it, and the reveal shows it as corridors like everywhere else.
        cand = [];
        for (j = 0; j < pocket.length; j++) pocketDoors(pocket[j], id, cand);
        if (cand.length) {
          n = cand[Rand.int(0, cand.length - 1)];
          open(n[0], n[1], n[2], n[3]);
        }
      }

      // --- 4. the band's own furniture, which needs the three maps this
      //        function owns: the true corridor, the dead ones, and what a
      //        pulse can actually get to.
      var reach = fillReach();
      placeDecoys(dead, reach);
      placeCrystalCell(dead, reach);

      function pocketDoors(cell, mine, out) {
        var c2 = cell[0], r2 = cell[1];
        function side(nc, nr) {
          if (nc < 0 || nc >= M.cols || nr < 0 || nr >= M.rows) return;
          if (!dead[hI(nr, nc)] || pid[hI(nr, nc)] === mine) return;
          out.push([c2, r2, nc, nr]);
        }
        side(c2, r2 - 1); side(c2, r2 + 1); side(c2 - 1, r2); side(c2 + 1, r2);
      }
    }

    /* EVERY CELL A PULSE CAN GET TO AT ALL — a flood fill from the doors,
       through the openings. Step 3 above is allowed to leave a pocket sealed
       behind the main path, and `dead` marks those cells like any other: a key
       standing in one would be a board whose gate can never be unlocked, and a
       false gate over one is a gate nothing can ever fly into. So what the two
       are placed on is filtered through this, and never through `dead` alone. */
    function fillReach() {
      var seen = [], st = [], i, cur, c, r;
      for (i = 0; i < M.rows * M.cols; i++) seen.push(0);
      function step(nc, nr) {
        if (nc < 0 || nc >= M.cols || nr < 0 || nr >= M.rows || seen[hI(nr, nc)]) return;
        seen[hI(nr, nc)] = 1; st.push([nc, nr]);
      }
      for (i = 0; i < M.cols; i++)
        if (!hSolid[hI(M.rows, i)]) step(i, M.rows - 1);
      while (st.length) {
        cur = st.pop(); c = cur[0]; r = cur[1];
        if (!hSolid[hI(r, c)]) step(c, r - 1);
        if (!hSolid[hI(r + 1, c)]) step(c, r + 1);
        if (!vSolid[vI(r, c)]) step(c - 1, r);
        if (!vSolid[vI(r, c + 1)]) step(c + 1, r);
      }
      return seen;
    }

    /* THE FALSE GATES. A hole in the ceiling over a cell of a DEAD corridor —
       never over the true one, which would be a second way out and would make
       the board a lie rather than a riddle. Two gates are kept two columns
       apart so the ceiling reads as separate doorways instead of one wide one.
       A gate over a sealed pocket (a corridor the main path walled off) is a
       gate no pulse can ever reach: harmless, and rare enough not to be worth
       carving the board again for. */
    function placeDecoys(dead, reach) {
      var want = featDecoys(), cand = [], c, i, k, pick;
      decoys = [];
      if (!want) return;
      for (c = 0; c < M.cols; c++)
        if (Math.abs(c - exitCol) >= 2 && dead[hI(0, c)] && !mainCell[hI(0, c)] && reach[hI(0, c)])
          cand.push(c);
      for (i = 0; i < want && cand.length; i++) {
        k = Rand.int(0, cand.length - 1);
        pick = cand[k];
        hSolid[hI(0, pick)] = 0;
        decoys.push({ c: pick, dead: false, burn: 0 });
        for (k = cand.length - 1; k >= 0; k--)
          if (Math.abs(cand[k] - pick) < 2) cand.splice(k, 1);
      }
    }

    /* WHERE THE KEY STANDS. In the bay it is a free-standing target: off the
       centre line, because a crystal straight above the cannon is a shot that
       comes straight back down, and the whole point of putting it there is the
       angle the player has to find to shatter it AND still make a door. In the
       maze it is a dead-end cell in the lower half of the board — deep enough
       to cost a pulse, shallow enough that a pulse can realistically get to
       it. */
    function placeCrystalCell(dead, reach) {
      var home = crystalHome(), deep = [], any = [], r, c, i, fx;
      crystal = null;
      if (!home) return;
      if (home === "bay") {
        fx = Rand.chance(0.5) ? Rand.range(0.12, 0.32) : Rand.range(0.68, 0.88);
        crystal = { home: "bay", fx: fx, fy: Rand.range(0.24, 0.52), cell: -1,
                    x: 0, y: 0, r: C.crystalR, alive: true };
        return;
      }
      for (r = 1; r <= M.rows - 2; r++) for (c = 0; c < M.cols; c++) {
        i = hI(r, c);
        if (mainCell[i] || !dead[i] || !reach[i]) continue;
        any.push(i);
        if (r >= Math.floor(M.rows * 0.45)) deep.push(i);
      }
      if (!deep.length) deep = any;
      if (!deep.length) return;                   // a board with no dead end at
                                                  // all cannot happen, but an
                                                  // unlocked gate beats a
                                                  // locked one with no key
      crystal = { home: "maze", fx: 0, fy: 0, cell: deep[Rand.int(0, deep.length - 1)],
                  x: 0, y: 0, r: C.crystalR, alive: true };
    }

    // The px of it, re-solved whenever Layout moves — the cell and the two
    // fractions are what the board actually stores.
    function placeCrystal() {
      var r, c;
      if (!crystal) return;
      if (crystal.home === "bay") {
        crystal.r = C.crystalR;
        crystal.x = field.left + (field.right - field.left) * crystal.fx;
        crystal.y = M.y1 + (field.bottom - M.y1) * crystal.fy;
      } else {
        r = Math.floor(crystal.cell / M.cols); c = crystal.cell - r * M.cols;
        crystal.r = Math.min(C.crystalR, Math.min(M.cw, M.ch) * 0.34);
        crystal.x = M.x0 + (c + 0.5) * M.cw;
        crystal.y = M.y0 + (r + 0.5) * M.ch;
      }
    }

    // Flood-fill from one mouth: does it reach the cell the ceiling is pierced
    // over? Exactly one of the six must, and it must be the one we carved.
    function reaches(mouth) {
      var seen = [], st = [], cur, c, r, i, c0 = mouthCol(mouth);
      function step(nc, nr) {
        if (nc < 0 || nc >= M.cols || nr < 0 || nr >= M.rows || seen[hI(nr, nc)]) return;
        seen[hI(nr, nc)] = 1; st.push([nc, nr]);
      }
      for (i = 0; i < M.rows * M.cols; i++) seen.push(0);
      for (i = 0; i < C.mouthW; i++) { st.push([c0 + i, M.rows - 1]); seen[hI(M.rows - 1, c0 + i)] = 1; }
      while (st.length) {
        cur = st.pop(); c = cur[0]; r = cur[1];
        if (r === 0 && c === exitCol) return true;
        if (!hSolid[hI(r, c)]) step(c, r - 1);
        if (!hSolid[hI(r + 1, c)]) step(c, r + 1);
        if (!vSolid[vI(r, c)]) step(c - 1, r);
        if (!vSolid[vI(r, c + 1)]) step(c + 1, r);
      }
      return false;
    }
    /* The corridor that WAS the way out, walked once at generation time and
       kept as a list of cell indices from the true mouth up to the exit. It is
       never read during play — only the post-mortem draws it. A breadth-first
       walk restricted to `mainCell` cannot wander: the carved path is the only
       thing marked, and it is a single corridor, so the parents chain straight
       back from the pierced ceiling to the door. */
    function traceTruePath() {
      var i, seen = [], prev = [], q = [], head = 0, cur, c, r, out = [];
      for (i = 0; i < M.rows * M.cols; i++) { seen.push(0); prev.push(-1); }
      function step(nc, nr, from) {
        var j;
        if (nc < 0 || nc >= M.cols || nr < 0 || nr >= M.rows) return;
        j = hI(nr, nc);
        if (seen[j] || !mainCell[j]) return;
        seen[j] = 1; prev[j] = from; q.push(j);
      }
      cur = hI(M.rows - 1, entryCol);
      seen[cur] = 1; q.push(cur);
      while (head < q.length) {
        cur = q[head++]; r = Math.floor(cur / M.cols); c = cur - r * M.cols;
        if (!hSolid[hI(r, c)]) step(c, r - 1, cur);
        if (!hSolid[hI(r + 1, c)]) step(c, r + 1, cur);
        if (!vSolid[vI(r, c)]) step(c - 1, r, cur);
        if (!vSolid[vI(r, c + 1)]) step(c + 1, r, cur);
      }
      truePath = [];
      cur = hI(0, exitCol);
      if (!seen[cur]) return;                       // cannot happen: validate() ran
      while (cur >= 0) { truePath.push(cur); cur = prev[cur]; }
      truePath.reverse();
    }

    /* One carve is not always a board this band can be played on: exactly one
       mouth must reach the exit, and the ceiling must have room for the false
       gates the band asks for — row 0 is mostly the true corridor on a narrow
       board, and a band that asked for two gates would quietly ship one. Both
       are cheap to test and a carve is cheap to redo, so the board is rolled
       until it can carry its own rules. */
    function generate() {
      var tries = 0, m, ok, want = featDecoys();
      do {
        carve();
        ok = 0;
        for (m = 0; m < MOUTHS; m++) if (reaches(m)) ok++;
      } while ((ok !== 1 || decoys.length < want) && ++tries < 24);
      traceTruePath();
    }
    function mouthCol(m) { return m * C.mouthW; }
    function colMouth(c) { return Math.floor(c / C.mouthW); }

    /* --- the segments -------------------------------------------------
       One object per collidable wall. NOTHING here is drawn for free: a wall is
       on screen only while its `lit` is burning down, which is what makes the
       board something the player echolocates instead of reads. `found` is the
       scoring flag — a wall pays once, the first time a pulse ever strikes it.

       The mouth row is the exception: every one of its walls is solid, and the
       ones over a throat carry `flap`, which the probe honours in one direction
       only (see probe): a rising pulse pushes through, a falling one is stopped. */
    function buildWalls() {
      var r, c, w;
      walls = []; hw = []; vw = []; wallCount = 0;
      for (r = 0; r <= M.rows; r++) for (c = 0; c < M.cols; c++) {
        w = { h: 1, c: c, r: r, solid: hSolid[hI(r, c)], flap: false,
              made: false, swing: 1,           // a valve a spent pulse left here
              mouth: -1, lock: false,          // the door it closes; the crystal's bar
              lit: 0, found: false, seg: [0, 0, 0, 0, 0], stamp: 0,
              x0: 0, y0: 0, x1: 0, y1: 0, wx: 0, wy: 0, ww: 0, wh: 0 };
        // The mouth row knows which door each of its panels belongs to, which
        // is all the surge needs to seal one.
        if (r === M.rows) { w.flap = w.solid === 0; w.solid = 1; if (w.flap) w.mouth = colMouth(c); }
        hw[hI(r, c)] = w; walls.push(w);
      }
      for (r = 0; r < M.rows; r++) for (c = 0; c <= M.cols; c++) {
        if (c === 0 || c === M.cols) { vw[vI(r, c)] = null; continue; }
        w = { h: 0, c: c, r: r, solid: vSolid[vI(r, c)], flap: false,
              made: false, swing: 1, mouth: -1, lock: false,
              lit: 0, found: false, seg: [0, 0, 0, 0, 0], stamp: 0,
              x0: 0, y0: 0, x1: 0, y1: 0, wx: 0, wy: 0, ww: 0, wh: 0 };
        vw[vI(r, c)] = w; walls.push(w);
      }
      for (r = 0; r < walls.length; r++) if (walls[r].solid) wallCount++;
      placeWalls();
      rollSegs();
    }
    function placeWalls() {
      var i, w, t = C.wallT, h2 = t / 2;
      for (i = 0; i < walls.length; i++) {
        w = walls[i];
        if (w.h) {
          w.x0 = M.x0 + w.c * M.cw; w.x1 = w.x0 + M.cw;
          w.y0 = w.y1 = M.y0 + w.r * M.ch;
          // every rect is grown by half a thickness at both ends, which is what
          // makes the junctions solid instead of leaving pinholes at the corners
          w.wx = w.x0 - h2; w.ww = M.cw + t; w.wy = w.y0 - h2; w.wh = t;
        } else {
          w.y0 = M.y0 + w.r * M.ch; w.y1 = w.y0 + M.ch;
          w.x0 = w.x1 = M.x0 + w.c * M.cw;
          w.wx = w.x0 - h2; w.ww = t; w.wy = w.y0 - h2;
          // The teeth between the mouths stop exactly ON the mouth line instead
          // of hanging half a thickness below it: that overhang was clipping
          // every pulse aimed at one of the outer doors. The corner is still
          // sealed once the flap shuts, by the mouth wall's own overhang.
          w.wh = M.ch + (w.r === M.rows - 1 ? h2 : t);
        }
      }
    }
    function rollSegs() {
      for (var i = 0; i < walls.length; i++) {
        var s = walls[i].seg;
        s[1] = Rand.range(-1, 1); s[2] = Rand.range(-1, 1);
        s[3] = Rand.range(-1, 1); s[4] = Rand.range(-1, 1);
      }
    }
    function hwAt(r, c) { return (r < 0 || r > M.rows || c < 0 || c >= M.cols) ? null : hw[hI(r, c)]; }
    function vwAt(r, c) { return (r < 0 || r >= M.rows || c < 0 || c > M.cols) ? null : vw[vI(r, c)]; }

    /* =================================================================
       COLLISION — circle against the wall segments of the 3x3 cells the pulse
       overlaps. The deepest overlap wins and its contact normal is written
       into HIT, so a corner deflects the pulse instead of mirroring it.
       ================================================================= */
    var HIT = { w: null, ux: 0, uy: 0, d: 0 };
    var probeStamp = 0;
    var CAND = [];                  // reused every probe: no per-substep garbage
    function probe(x, y, R, vy) {
      var c0 = Math.floor((x - R - M.x0) / M.cw), c1 = Math.floor((x + R - M.x0) / M.cw);
      var r0 = Math.floor((y - R - M.y0) / M.ch), r1 = Math.floor((y + R - M.y0) / M.ch);
      var best = null, bestD = 1e9, bnx = 0, bny = 0, bw = null;
      var r, c, i, n = 0, w, dx, dy, d2, ox, oy, d;
      probeStamp++;
      // One cell wider than the pulse's own box on every side: a wall's rect is
      // grown by half a thickness past its cell, so the stub of the wall NEXT
      // door reaches into this one. Miss it and a pulse slips through a corner.
      for (r = r0 - 1; r <= r1 + 1; r++) for (c = c0 - 1; c <= c1 + 1; c++) {
        CAND[n++] = hwAt(r, c); CAND[n++] = hwAt(r + 1, c);
        CAND[n++] = vwAt(r, c);  CAND[n++] = vwAt(r, c + 1);
      }
      for (i = 0; i < n; i++) {
        w = CAND[i];
        if (!w || !w.solid || w.stamp === probeStamp) continue;
        // A rising pulse pushes a flap open — unless the surge is standing on
        // that door, in which case it is a wall like any other and throws the
        // pulse back down into the bay.
        if (w.flap && vy < 0 && !(w.mouth >= 0 && mouths[w.mouth].seal)) continue;
        w.stamp = probeStamp;
        dx = x - clamp(x, w.wx, w.wx + w.ww);
        dy = y - clamp(y, w.wy, w.wy + w.wh);
        d2 = dx * dx + dy * dy;
        if (d2 > R * R || d2 >= bestD) continue;
        best = w; bestD = d2; bnx = dx; bny = dy; bw = w;
      }
      HIT.w = best;
      if (!best) return null;
      d = Math.sqrt(bestD);
      if (d > 0.0001) { HIT.ux = bnx / d; HIT.uy = bny / d; }
      else {                                       // dead centre: shortest way out
        ox = x - (bw.wx + bw.ww / 2); oy = y - (bw.wy + bw.wh / 2);
        if (Math.abs(ox) / bw.ww > Math.abs(oy) / bw.wh) { HIT.ux = ox < 0 ? -1 : 1; HIT.uy = 0; }
        else { HIT.ux = 0; HIT.uy = oy < 0 ? -1 : 1; }
      }
      HIT.d = d;
      return best;
    }

    /* --- how a pulse moves -------------------------------------------
       The heading is kept inside a cone: never flatter than minRatio, never
       steeper either. A pulse that went flat would shuttle along one corridor
       for ever; one that went vertical would shuttle inside one cell. Between
       those two floors it always makes progress on both axes, which is what
       turns a bouncing ball into something that actually searches a maze. */
    function cone(b) {
      var S = C.ballSpeed, m = S * C.minRatio;
      var sx = b.vx < 0 ? -1 : 1, sy = b.vy < 0 ? -1 : 1;
      var ax = Math.abs(b.vx), ay = Math.abs(b.vy);
      if (ax < m) { ax = m; ay = Math.sqrt(S * S - m * m); }
      else if (ay < m) { ay = m; ax = Math.sqrt(S * S - m * m); }
      b.vx = sx * ax; b.vy = sy * ay;
    }
    // The lift: a pulse CLIMBS. The speed never changes, only the heading bends
    // upward, so the charge gauge stays an honest clock.
    function steer(b, h) {
      var sp;
      b.vy -= C.lift * h;
      sp = Math.sqrt(b.vx * b.vx + b.vy * b.vy) || 1;
      b.vx = b.vx / sp * C.ballSpeed; b.vy = b.vy / sp * C.ballSpeed;
      cone(b);
    }
    function bounce(b, ux, uy) {
      var vn = b.vx * ux + b.vy * uy, a;
      if (vn < 0) { b.vx -= 2 * vn * ux; b.vy -= 2 * vn * uy; }
      // A hair of noise on every contact. Without it a pulse can lock into a
      // periodic orbit and rattle between the same two walls until it dies.
      a = Math.atan2(b.vy, b.vx) + Rand.range(-C.bounceJitter, C.bounceJitter);
      b.vx = Math.cos(a) * C.ballSpeed; b.vy = Math.sin(a) * C.ballSpeed;
      b.free = false;               // the shot is over: from here it climbs
      cone(b);
    }

    /* =================================================================
       THE ARENA FENCE — the two sides and the floor. They carry no painted
       frame beyond a dim line: a contact drops a `zap` on that side, which
       lights it as a crackling arc, white-hot at the impact and dying out
       toward the two corners. Same fence as games/bouncetry.
       ================================================================= */
    var SIDE_L = 0, SIDE_R = 1, SIDE_B = 2;
    var ZAP_SEGS = 24;
    var ZAP_MERGE = 90;
    var ZAP_PASSES = [[20, 0.10], [11, 0.22], [5, 0.5], [2.2, 1]];

    function zapSpan(s) { return s === SIDE_B ? field.right - field.left : field.bottom - field.top; }
    function zapBase(s) { return s === SIDE_B ? field.left : field.top; }
    function zapEdge(s) { return s === SIDE_L ? field.left : s === SIDE_R ? field.right : field.bottom; }
    function zapRoll(z) {
      z.seg.length = 0;
      for (var i = 0; i <= ZAP_SEGS; i++) z.seg.push(Rand.range(-1, 1));
      z.seg[0] = 0; z.seg[ZAP_SEGS] = 0;           // pinned to the two corners
    }
    function zap(side, x, y, power, col) {
      var len = zapSpan(side);
      var p = clamp((side === SIDE_B ? x - field.left : y - field.top) / len, 0, 1);
      var i, z;
      for (i = 0; i < zaps.length; i++) {          // re-light, never stack
        z = zaps[i];
        if (z.side === side && Math.abs(z.p - p) * len < ZAP_MERGE) {
          z.t = 0; z.p = p; z.col = col; z.power = Math.max(z.power, power);
          zapRoll(z);
          return;
        }
      }
      z = { side: side, p: p, t: 0, life: 0.3 + 0.34 * power, power: power,
            col: col, crackle: 0, seg: [] };
      zapRoll(z);
      zaps.push(z);
    }
    function zapAll(power) {
      zap(SIDE_L, field.left, (field.top + field.bottom) / 2, power, ARC);
      zap(SIDE_R, field.right, (field.top + field.bottom) / 2, power, ARC);
      zap(SIDE_B, (field.left + field.right) / 2, field.bottom, power, ARC);
    }
    function updateZaps(dt) {
      for (var i = zaps.length - 1; i >= 0; i--) {
        var z = zaps[i];
        z.t += dt;
        if (z.t >= z.life) { zaps.splice(i, 1); continue; }
        z.crackle -= dt;
        if (z.crackle <= 0 && z.t < z.life * 0.55) { zapRoll(z); z.crackle = 0.045; }
      }
    }
    // createLinearGradient only accepts offsets inside 0..1, and an impact near
    // a corner pushes the lit window past both ends.
    function addStop(g, at, col) { if (at > 0 && at < 1) g.addColorStop(at, col); }
    function drawZap(z) {
      var k = clamp(1 - z.t / z.life, 0, 1);
      var flash = Math.pow(k, 0.55);
      var horiz = z.side === SIDE_B;
      var len = zapSpan(z.side), base = zapBase(z.side), edge = zapEdge(z.side);
      var w = (0.08 + 0.14 * z.power) * (0.85 + 0.4 * (1 - k));
      var amp = (6 + 15 * z.power) * (0.3 + 0.7 * k);
      var inward = (z.side === SIDE_R || z.side === SIDE_B) ? -1 : 1;
      var i, q, u, d, o, x, y, g, a, col, px, py;

      ctx.save();
      ctx.lineCap = "round"; ctx.lineJoin = "round";
      for (q = 0; q < ZAP_PASSES.length; q++) {
        a = ZAP_PASSES[q][1] * flash;
        col = q === ZAP_PASSES.length - 1 ? "#ffffff" : z.col;
        g = horiz ? ctx.createLinearGradient(base, 0, base + len, 0)
                  : ctx.createLinearGradient(0, base, 0, base + len);
        g.addColorStop(0, rgba(col, 0));
        addStop(g, z.p - w * 1.8, rgba(col, 0));
        addStop(g, z.p - w, rgba(col, a * 0.2));
        addStop(g, z.p, rgba(col, a));
        addStop(g, z.p + w, rgba(col, a * 0.2));
        addStop(g, z.p + w * 1.8, rgba(col, 0));
        g.addColorStop(1, rgba(col, 0));
        ctx.strokeStyle = g;
        ctx.lineWidth = ZAP_PASSES[q][0] * (0.35 + 0.65 * k);
        ctx.beginPath();
        for (i = 0; i <= ZAP_SEGS; i++) {
          u = i / ZAP_SEGS;
          d = base + u * len;
          o = z.seg[i] * amp * Math.max(0, 1 - Math.abs(u - z.p) / (w * 1.4));
          if (o * inward < 0) o *= 0.35;           // barely any overshoot outward
          x = horiz ? d : edge + o;
          y = horiz ? edge + o : d;
          if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
        }
        ctx.stroke();
      }
      px = horiz ? base + z.p * len : edge;        // the contact node itself
      py = horiz ? edge : base + z.p * len;
      ctx.globalAlpha = flash;
      ctx.fillStyle = rgba(z.col, 0.5);
      ctx.beginPath(); ctx.arc(px, py, 4 + 20 * z.power * k, 0, TAU); ctx.fill();
      ctx.fillStyle = "#ffffff";
      ctx.beginPath(); ctx.arc(px, py, 2 + 7 * z.power * k, 0, TAU); ctx.fill();
      ctx.restore();
    }

    /* =================================================================
       THE ECHO — what a contact does to the map.
       ================================================================= */
    function popAt() { return { x: Layout.cx, y: M.y1 + 46 }; }

    // The two walls in line with the one that was struck light up as well: a
    // contact reads a whole face of the corridor instead of a 110 px stub, and
    // it is the only reason a player can piece the board together at all.
    function inline2(w, out) {
      out.length = 0;
      if (w.h) { out.push(hwAt(w.r, w.c - 1), hwAt(w.r, w.c + 1)); }
      else { out.push(vwAt(w.r - 1, w.c), vwAt(w.r + 1, w.c)); }
      return out;
    }
    var NB = [];
    function echo(w, x, y, power) {
      var i, n, fresh = !w.found;
      w.lit = 1;
      // The crystal's bar answers in its own colour, and the first time a
      // player ever meets it it is named (the guide's "crystal" page): a pulse
      // rattling under a sealed ceiling with nothing to explain it is the one
      // way this board could read as broken.
      if (w.lock) {
        lockFlare = 1;
        Notify.learn("crystal", "Exit sealed", { sub: "Break the crystal", icon: "lock" });
      }
      inline2(w, NB);
      for (i = 0; i < NB.length; i++) {
        n = NB[i];
        if (n && n.solid) n.lit = Math.max(n.lit, 0.62);
      }
      bounces++;
      score += C.bounceScore;
      // Six pulses in 42 px corridors bounce dozens of times a second, so the
      // click and the sparks are rate-limited to what an ear and an eye can
      // actually separate — the arcs themselves carry the rest.
      if (clock - lastWall > 0.07) {
        lastWall = clock;
        Sound.clip("wall", 0.26, Rand.range(0.94, 1.2));
        Fx.burst(x, y, { color: ["#ffffff", ARC], count: 3, speed: 170, life: 0.2, size: 3 });
      }
      if (fresh) {
        // A wall pays once, the first time a pulse ever finds it: the score is
        // how much of the board the player has actually touched.
        w.found = true;
        mapped++;
        score += C.mapScore;
        HUD.setRight(mapped, "Walls");
        Sound.clip("map", 0.5, Rand.range(0.96, 1.14));
        Fx.ring(x, y, { from: 3, to: 30 + 18 * power, color: ARC, width: 3, life: 0.22 });
        if (clock - lastText > 0.2) {
          lastText = clock;
          Pop.text(x, y - 14, "+" + C.mapScore, { color: "#dffcff", size: 22, life: 0.6, tier: 1 });
        }
        if (mapped % 25 === 0) {
          Pop.show("combo", { word: mapped + Lang.t(" walls"), sub: "Found", at: popAt() });
          Sound.clip("power", 0.3, 1.35);
        }
      }
      HUD.setScore(score);
    }

    /* =================================================================
       THE FLAPS — the mouth row is six one-way valves. The physics is already
       handled (probe skips a `flap` wall for a rising pulse, and stops a
       falling one dead); all that is left here is to kick the panels open when
       one goes through and let them drop back. A door is never spent: the next
       pulse pushes the same flap open again.
       ================================================================= */
    function kickFlap(m) {
      var cx = M.x0 + (mouthCol(m) + C.mouthW / 2) * M.cw;
      mouths[m].t = 0;
      Sound.clip("flap", 0.7, Rand.range(0.94, 1.08));
      Fx.shake(4, 0.14);
      Fx.burst(cx, M.y1, { color: [ARC, "#ffffff"], count: 8, speed: 220, life: 0.3 });
    }

    /* =================================================================
       THE VALVES — the rack turning into plumbing.

       A pulse that burns its charge out inside the maze does not just vanish:
       it COLLAPSES INTO THE OPENING IT LAST CLIMBED THROUGH and becomes a
       one-way valve there, exactly like the six at the mouths. The physics is
       already written — probe() lets a rising pulse push a `flap` open and
       stops a falling one dead — so the whole mechanic is which opening to
       pick and how to show it.

       What it does to the run: every corridor a pulse died in now only flows
       upward. Stack two or three valves in the same corridor and a later pulse
       can no longer rattle back down it, so it is pushed at the ceiling
       instead. The board is at its cruellest with a full rack and kindest with
       the last pulse in it, which is what makes losing pulses a trade rather
       than a straight loss.
       ================================================================= */
    // The opening a spent pulse turns into: the one it last crossed, or failing
    // that the nearest open horizontal slot around it. Horizontal only — a
    // valve has to be a floor to be a check valve.
    function valveSlot(b) {
      var best = null, bd = 1e9, r, c, w, dx, dy, d, cc, rr2;
      if (b.gap && !b.gap.solid) return b.gap;
      cc = clamp(Math.floor((b.x - M.x0) / M.cw), 0, M.cols - 1);
      rr2 = clamp(Math.floor((b.y - M.y0) / M.ch), 0, M.rows - 1);
      for (r = Math.max(1, rr2 - 2); r <= Math.min(M.rows - 1, rr2 + 2); r++)
        for (c = Math.max(0, cc - 2); c <= Math.min(M.cols - 1, cc + 2); c++) {
          w = hwAt(r, c);
          if (!w || w.solid) continue;
          dx = M.x0 + (c + 0.5) * M.cw - b.x; dy = M.y0 + r * M.ch - b.y;
          d = dx * dx + dy * dy;
          if (d < bd) { bd = d; best = w; }
        }
      return best;
    }
    function forgeValve(b) {
      var w = valveSlot(b), mx, my;
      if (!w) return;
      w.solid = 1; w.flap = true; w.made = true; w.swing = 0;
      // It is the player's own doing, so it never pays the map bonus: `mapped`
      // stays a count of the BOARD the run uncovered.
      w.found = true;
      valves.push(w);
      mx = (w.x0 + w.x1) / 2; my = w.y0;
      score += C.valveScore;
      HUD.setScore(score); HUD.punch(VALVE);
      Sound.clip("flap", 0.85, 0.82);
      Sound.clip("power", 0.32, 1.5);
      Fx.shake(6, 0.18);
      Fx.ring(mx, my, { from: 8, to: 92, color: VALVE, width: 5, life: 0.42 });
      Fx.burst(mx, my, { color: [VALVE, "#ffffff"], count: 12, speed: 240, life: 0.4, size: 4 });
      // Discreet on purpose: a valve is a consolation, not a win. The first
      // one a player ever forges is NAMED (the guide's "valves" page), and
      // every one after that is a plain score callout.
      if (!Notify.learn("valves", "One-way valve", { sub: "Pulses go up, never back down" }))
        Pop.show("score", { word: "One-way valve", sub: "+" + C.valveScore, at: popAt(), hold: 240 });
    }
    // A later pulse pushing one of them open, on its way up.
    function kickValve(w) {
      w.swing = 0; w.lit = Math.max(w.lit, 0.8);
      Sound.clip("flap", 0.42, Rand.range(1.18, 1.3));
      Fx.burst((w.x0 + w.x1) / 2, w.y0, { color: [VALVE, "#ffffff"], count: 5,
                                          speed: 180, life: 0.24, size: 3 });
    }

    /* =================================================================
       THE FALSE GATES, THE CRYSTAL AND THE SURGE — the three rules of the
       climb, in the order a player meets them.
       ================================================================= */
    /* A pulse climbed into a gate that was never the way out. It is eaten —
       nothing comes back, and there is no valve to forge, because it left the
       board — and the gate goes out with it. What the run bought is the
       answer: one of the three is now crossed off for good, and the ceiling
       remembers it (the hole is welded shut, so a later pulse bounces off it
       like any other stretch of roof). */
    function burnDecoy(d, b) {
      var w = hwAt(0, d.c), mx = M.x0 + (d.c + 0.5) * M.cw;
      d.dead = true; d.burn = 1;
      hSolid[hI(0, d.c)] = 1;
      if (w) { w.solid = 1; w.found = true; }     // it never pays the map bonus
      b.alive = false;
      score += C.decoyScore;
      HUD.setScore(score); HUD.punch(SURGE);
      Sound.clip("fizzle", 0.85, 0.72);
      Sound.clip("fail", 0.45, 1.25);
      Fx.flash(SURGE, 0.22); Fx.shake(13, 0.32);
      Fx.ring(mx, M.y0, { from: 12, to: 190, color: SURGE, width: 6, life: 0.45 });
      Fx.burst(mx, M.y0, { color: [SURGE, "#ffffff"], count: 18, speed: 250,
                           life: 0.45, size: 5 });
      Overlay.vignette(rgba(SURGE, 0.55), 1, 700);
      Notify.learn("decoys", "False exit", { sub: "Only the true exit sends rings" });
    }

    /* The key, taken. The bar comes off the gate in the same frame, which is
       the whole reason the crystal is lit from the first frame: the player has
       something to aim at, and the gate has something to wait for. */
    function shatterCrystal() {
      var i;
      crystal.alive = false;
      score += C.crystalScore;
      HUD.setScore(score); HUD.punch(CRYSTAL);
      for (i = 0; i < lockWalls.length; i++) { lockWalls[i].solid = 0; lockWalls[i].lock = false; }
      lockWalls = [];
      gateFlare = 1; lockFlare = 1;
      Sound.clip("escape", 0.55, 1.34);
      Sound.clip("power", 0.8, 0.92);
      Fx.flash("#ffffff", 0.3); Fx.shake(14, 0.36); Fx.freeze(0.04);
      Fx.ring(crystal.x, crystal.y, { from: 8, to: 220, color: CRYSTAL, width: 7, life: 0.5 });
      Fx.burst(crystal.x, crystal.y, { color: [CRYSTAL, "#ffffff", "#ffd2f4"], count: 24,
                                       speed: 300, life: 0.55, size: 5 });
      Overlay.vignette(rgba(CRYSTAL, 0.8), 1, 900);
    }

    /* THE CEILING SHUTS — and it shuts when the round STARTS, never before.
       The bar is drawn in the gap, which is exactly where the true gate's
       beacon comes out of, so a board that was barred through the reveal spent
       the one second the player has to read the ceiling showing three sealed
       holes with nothing to tell them apart. On the last band, which is the
       only one that carries a crystal AND false gates, that made the board
       unreadable. The reveal is the LOOK at the board, so the board is open
       for it; the crystal takes the ceiling the moment the lights go out, and
       the shatter gives it back.

       The bar goes over EVERY gate, and that is not decoration: a bar on the
       true one alone would be a sign saying which of the three is the way out,
       and the false gates of the last band would stop being false. So while
       the crystal stands the ceiling is shut, all of it — no pulse can be
       spent on a door before the key is taken — and the shatter lifts every
       bar in the same frame. */
    function sealGates() {
      var i;
      if (!crystal || !crystal.alive || lockWalls.length) return;
      lockGate(exitCol);
      for (i = 0; i < decoys.length; i++) lockGate(decoys[i].c);
      if (!lockWalls.length) return;
      lockFlare = 1;                               // they land lit, so the
      Sound.clip("flap", 0.7, 0.72);               // player sees them land
    }

    // One gate, barred. The wall is `found` from the start: the bar is the
    // crystal's, not a stretch of board to be discovered, and it must never
    // pay the map bonus.
    function lockGate(c) {
      var w = hwAt(0, c);
      if (!w) return;
      w.solid = 1; w.lock = true; w.found = true;
      lockWalls.push(w);
    }

    // A pulse against the crystal: it shatters, and the pulse ricochets off it
    // the way it would off anything else. That ricochet IS the mechanic when
    // the crystal stands in the bay — the shot has to break the key and still
    // find a door.
    function hitCrystal(b, R) {
      var dx = b.x - crystal.x, dy = b.y - crystal.y;
      var d = Math.sqrt(dx * dx + dy * dy) || 1, reach = crystal.r + R;
      if (d > reach) return;
      b.x = crystal.x + dx / d * reach;
      b.y = crystal.y + dy / d * reach;
      shatterCrystal();
      bounce(b, dx / d, dy / d);
    }

    /* THE SURGE. The gap's tour of the doors: EVERY door, in a random order,
       and then the same order again. Every door, because the fence is shut
       everywhere else — a door the gap never visits would be a door no pulse
       can ever take, which would quietly delete a corridor from the board and
       hand the player the answer by elimination. */
    function rollSurge() {
      var i, k, t;
      surgeSeq = []; surgeI = 0; surgeT = 0; surgeFlash = 0;
      if (!featSurge()) return;
      for (i = 0; i < MOUTHS; i++) surgeSeq.push(i);
      for (i = surgeSeq.length - 1; i > 0; i--) {
        k = Rand.int(0, i); t = surgeSeq[i]; surgeSeq[i] = surgeSeq[k]; surgeSeq[k] = t;
      }
    }
    // Which doors are shut right now: all of them but the one the gap is on.
    // Written on the mouths themselves, because that is where probe() reads it.
    function applySeal() {
      var open = (surgeSeq && surgeSeq.length && phase !== "reveal") ? surgeSeq[surgeI] : -1, i;
      for (i = 0; i < MOUTHS; i++)
        mouths[i].seal = surgeSeq.length ? (i !== open && !mouths[i].freed) : false;
    }
    function jumpSurge(loud) {
      surgeFlash = C.surgeFlash;
      rollSurgeNoise();
      if (loud) Sound.clip("power", 0.4, 1.72);
      else Sound.clip("power", 0.22, 1.72);
    }
    function stepSurge(dt) {
      if (!surgeSeq || !surgeSeq.length) return;
      if (surgeFlash > 0) surgeFlash = Math.max(0, surgeFlash - dt);
      surgeCrackle -= dt;
      if (surgeCrackle <= 0) { rollSurgeNoise(); surgeCrackle = 0.05; }
      surgeT += dt;
      while (surgeT >= C.surgePeriod) {
        surgeT -= C.surgePeriod;
        surgeI = (surgeI + 1) % surgeSeq.length;
        applySeal();
        jumpSurge(false);
      }
    }
    // A pulse that met the wire instead of the gap. It dies ON the door: the
    // whole shot is the price of firing on the wrong beat.
    //
    // The door is spent too — it stopped one pulse and that is all it gets. It
    // burns out, stays open for the rest of the round, and leaves the tour (see
    // freeMouth). The pulse has to die for that to hold: one thrown back into
    // the bay would keep climbing and take two or three more doors down on the
    // ricochet, and a single bad shot would open the fence end to end.
    function surgeHit(b, w) {
      var mx = M.x0 + (mouthCol(w.mouth) + C.mouthW / 2) * M.cw;
      surgeFlash = Math.max(surgeFlash, C.surgeFlash * 2.4);
      Sound.clip("flap", 0.55, 0.7);
      Sound.clip("fizzle", 0.4, 1.3);
      Fx.shake(8, 0.22);
      Fx.burst(mx, M.y1, { color: [SURGE, "#ffffff"], count: 12, speed: 260,
                           life: 0.35, size: 4 });
      // the pulse itself, going up on the wire. Not fizzle(): that is a pulse
      // running out of charge, and it leaves a valve behind where it died.
      b.alive = false;
      Fx.burst(b.x, b.y, { color: [SURGE, "#ffffff", DYING], count: 20, speed: 300,
                           life: 0.5, size: 5 });
      Fx.ring(b.x, b.y, { from: 6, to: 84, color: SURGE, width: 5, life: 0.4 });
      freeMouth(w.mouth, mx);
    }
    // A door taken out of the fence for good. The tour drops it — the gap would
    // otherwise spend a beat standing on a hole — and `surgeI` is kept on the
    // door it is on so the cycle does not skip or stutter at the seam. When the
    // last door goes the sequence empties, which is the same state as a board
    // with no fence at all: applySeal clears every seal and drawSurge draws
    // nothing.
    function freeMouth(m, mx) {
      var at = surgeSeq ? surgeSeq.indexOf(m) : -1;
      if (mouths[m].freed) return;
      mouths[m].freed = true;
      if (at >= 0) {
        surgeSeq.splice(at, 1);
        if (at < surgeI) surgeI--;
        if (surgeI >= surgeSeq.length) surgeI = 0;
      }
      applySeal();
      Fx.ring(mx, M.y1, { from: 14, to: 130, color: SURGE, width: 5, life: 0.4 });
      Sound.clip("power", 0.45, 1.1);
      Pop.show("streak", { word: "Door forced", sub: "Open for good" });
    }

    /* =================================================================
       EVENTS
       ================================================================= */
    function refreshHUD() {
      HUD.setLeft(queue, "Pulses");
      HUD.setRight(mapped, "Walls");
    }
    function onDepth(b) {
      var climbed = M.rows - deepest;
      score += C.depthScore;
      HUD.setScore(score); HUD.punch(EXIT_COL);
      Sound.clip("deep", 0.3, 0.94 + climbed * 0.07);
      Fx.ring(b.x, b.y, { from: 10, to: 90, color: EXIT_COL, width: 4, life: 0.34 });
      // No callout for a row: the climb is what the whole board is doing, the
      // ring and the chime already mark it, and a green sticker every row was
      // sitting on top of the one thing the player is reading.
    }
    function fizzle(b) {
      b.alive = false;
      Sound.clip("fizzle", 0.3, Rand.range(0.94, 1.1));
      Fx.burst(b.x, b.y, { color: [DYING, "#ffffff", "#ffb0cd"], count: 16, speed: 250,
                           life: 0.5, size: 5 });
      Fx.ring(b.x, b.y, { from: 6, to: 72, color: DYING, width: 5, life: 0.4 });
      // What is left of it stays in the maze as a valve — but only if it ever
      // got in: a pulse that died in the launch bay has nothing to seal.
      if (b.inMaze) forgeValve(b);
    }
    function escape(b) {
      var gain;
      if (escaped) return;
      escaped = true;
      b.alive = false;
      // Every pulse still in the rack pays: a player who READ the board beats a
      // player who worked through all six doors by elimination.
      spare = queue;
      gain = C.escapeBonus + spare * C.spareBonus;
      score += gain;
      HUD.setScore(score); HUD.punch(EXIT_COL);
      gateFlare = 1;
      Sound.clip("escape", 1);
      Confetti.burst(46);
      Fx.flash("#ffffff", 0.5); Fx.shake(16, 0.42); Fx.freeze(0.05);
      Fx.ring(b.x, M.y0, { from: 20, to: 320, color: EXIT_COL, width: 10, life: 0.6 });
      Overlay.vignette(rgba(EXIT_COL, 0.9), 1, 1000);
      Pop.show("ultra", { word: perfectRun() ? Lang.t("Perfect read!") : Lang.t("Escaped!"),
                          sub: "+" + gain, hold: 900,
                          at: { x: Layout.cx, y: M.y0 + M.ch * M.rows * 0.42 } });
      // What the rack was worth is priced on the END SCREEN, on its own row
      // (Bonus N pulses): a second callout under the hero one only competed
      // with it, and the escape is the moment, not the arithmetic.
      phase = "over"; endT = -1.1;                 // let the callout land first
      for (var i = 0; i < balls.length; i++) balls[i].alive = false;
    }

    function fire() {
      var mx, my;
      if (queue <= 0 || clock - lastShot < C.shotCooldown) return;
      mx = cannon.x + Math.cos(aimA) * C.muzzle;
      my = cannon.y + Math.sin(aimA) * C.muzzle;
      queue--; fired++; lastShot = clock; recoil = 1;
      // `free` is the honest part of the sight: until the first contact a pulse
      // travels the exact straight line the aim line drew. Only then does the
      // lift and the cone take over.
      balls.push({ x: mx, y: my, vx: Math.cos(aimA) * C.ballSpeed, vy: Math.sin(aimA) * C.ballSpeed,
                   life: C.ballLife, alive: true, inMaze: false, free: true,
                   // the row it is in, and the last opening it crossed: that
                   // opening is the valve it leaves behind when it burns out
                   row: null, gap: null });
      refreshHUD();
      Sound.clip("shoot", 0.4, Rand.range(0.97, 1.07));
      Fx.shake(9, 0.2);
      Fx.burst(mx, my, { color: [PULSE.core, "#ffffff"], count: 12, speed: 380,
                         life: 0.3, angle: aimA, spread: 1.0 });
      Fx.ring(mx, my, { from: 10, to: 78, color: PULSE.core, width: 5, life: 0.26 });
      if (queue === 1) Pop.show("alert", { word: "Last pulse", at: "bottom" });
    }

    function stepBall(b, h) {
      var R = C.ballR, w, hitW, c, row, ux, uy, guard, sill;
      if (!b.free) steer(b, h);
      b.x += b.vx * h; b.y += b.vy * h;

      // the arena: the two sides and the floor
      if (b.x - R < field.left) {
        b.x = field.left + R; zap(SIDE_L, b.x, b.y, clamp(Math.abs(b.vx) / C.ballSpeed, 0.3, 1), ARC);
        bounce(b, 1, 0); bounces++; score += C.bounceScore;
      } else if (b.x + R > field.right) {
        b.x = field.right - R; zap(SIDE_R, b.x, b.y, clamp(Math.abs(b.vx) / C.ballSpeed, 0.3, 1), ARC);
        bounce(b, -1, 0); bounces++; score += C.bounceScore;
      }
      if (b.y + R > field.bottom) {
        b.y = field.bottom - R; zap(SIDE_B, b.x, b.y, clamp(Math.abs(b.vy) / C.ballSpeed, 0.3, 1), ARC);
        bounce(b, 0, -1); bounces++; score += C.bounceScore;
      }

      // the maze. The push-out is iterated: in a corner, clearing one wall can
      // bury the pulse in the other, and a single pass would then eject it on
      // the WRONG side of a 16 px bar — into a corridor it has no business
      // being in, which would quietly break the one-true-entrance rule. The
      // reflection still uses the FIRST, deepest contact.
      w = probe(b.x, b.y, R, b.vy);
      if (w) {
        hitW = w; ux = HIT.ux; uy = HIT.uy; guard = 0;
        while (w && guard++ < 3) {
          b.x += HIT.ux * (R - HIT.d + 0.5); b.y += HIT.uy * (R - HIT.d + 0.5);
          w = probe(b.x, b.y, R, b.vy);
        }
        echo(hitW, b.x - ux * R * 0.4, b.y - uy * R * 0.4,
             clamp(Math.sqrt(b.vx * b.vx + b.vy * b.vy) / C.ballSpeed, 0.3, 1));
        // the wire: the pulse ends here, so nothing below runs for it
        if (hitW.mouth >= 0 && mouths[hitW.mouth].seal && uy > 0) { surgeHit(b, hitW); return; }
        bounce(b, ux, uy);
      }

      // the key, if this board has one and it is still standing
      if (crystal && crystal.alive) hitCrystal(b, R);

      // clear of the mouth row: the flap it pushed through drops back behind it
      if (!b.inMaze && b.y + R < M.y1 - C.wallT) {
        b.inMaze = true;
        c = clamp(Math.floor((b.x - M.x0) / M.cw), 0, M.cols - 1);
        kickFlap(colMouth(c));
      }
      // out through the ceiling — which, with the false gates up, is no longer
      // the same thing as winning
      if (b.y < M.y0) { topOut(b); return; }
      // depth, counted only once a pulse is really inside
      if (b.inMaze) {
        row = Math.floor((b.y - M.y0) / M.ch);
        if (row >= 0 && row < deepest) { deepest = row; onDepth(b); }
        // Which openings it goes through: the last one is what it becomes when
        // its charge runs out, and a valve already standing in one is kicked
        // as it climbs past. The ceiling row is left alone — the exit is never
        // anything but the exit.
        c = clamp(Math.floor((b.x - M.x0) / M.cw), 0, M.cols - 1);
        if (b.row == null) b.row = row;
        if (row !== b.row) {
          sill = hwAt(Math.max(row, b.row), c);
          if (sill && Math.max(row, b.row) > 0 && Math.max(row, b.row) < M.rows) {
            if (!sill.solid) b.gap = sill;
            else if (sill.made && row < b.row) kickValve(sill);
          }
          b.row = row;
        }
      }
    }

    /* Through the roof: the way out, a gate that never was, or — on a corner
       squeeze past a solid ceiling — neither, in which case the pulse is put
       back under the roof rather than allowed to leave the board. */
    function topOut(b) {
      var c = clamp(Math.floor((b.x - M.x0) / M.cw), 0, M.cols - 1), i;
      if (c === exitCol) { escape(b); return; }
      for (i = 0; i < decoys.length; i++)
        if (decoys[i].c === c && !decoys[i].dead) { burnDecoy(decoys[i], b); return; }
      b.y = M.y0 + C.ballR + 1;
      bounce(b, 0, 1);
    }

    /* =================================================================
       THE RUN
       ================================================================= */
    /* The look at the board is over and the round starts — including the
       fence, which comes up with the lights going out and turns from there.
       There is no phase of its own for it: a cycle shown on a paused board is
       a thing to memorise, and this one is a thing to TIME. It is learned by
       firing, which is also how everything else in this game is learned. */
    function goDark() {
      phase = "play"; darkT = 0;
      surgeI = 0; surgeT = 0; applySeal();
      sealGates();                                 // the crystal takes the
      Sound.clip("dark", 0.7);                     // ceiling, not before
      zapAll(0.5);                                 // the arena flashes once, and
      if (surgeSeq.length) {                       // that is the last of it
        jumpSurge(true);
        // the fence comes up with the dark: named once ever (guide "fence")
        Notify.learn("fence", "Live fence", { sub: "Fire through the gap as it moves" });
      }
    }
    // What fraction of the board is drawn for free right now: 1 during the
    // opening reveal, then the fade, then nothing at all, ever.
    function revealLevel() {
      if (phase === "reveal") return 1;
      // The post-mortem is the only other time the board is drawn for free: the
      // power comes back with a flicker and then stays up to the end screen.
      if (phase === "recap") {
        if (recapStep < 1) return 0;
        return clamp((recapT - C.recapSurge) / 0.12, 0, 1) *
               (0.92 + 0.08 * Math.sin(recapT * 34));
      }
      return darkT < C.revealFade ? 1 - darkT / C.revealFade : 0;
    }
    // The scan front of the post-mortem, in design px: every wall at or below it
    // is powered up. Parked below the board at every other time, so the grid is
    // whole whenever anything else draws it.
    function recapFront() {
      var t;
      if (phase !== "recap") return -1e9;           // nothing else scans anything
      if (recapStep < 1) return 1e9;                // still dark
      t = (recapT - C.recapSurge) / C.recapSweep;
      if (t >= 1) return -1e9;
      t = t * t * (3 - 2 * t);
      return M.y1 - (M.y1 - field.top) * t;
    }
    function skipReveal() {
      if (revealT < C.revealSkipAfter) return;
      goDark();
    }

    function aimAt(p) {
      var dx = p.x - cannon.x, dy = p.y - cannon.y, lim;
      if (dy > -40) dy = -40;                      // never aim into the floor
      lim = C.minAimDeg * Math.PI / 180;
      aimA = clamp(Math.atan2(dy, dx), -Math.PI + lim, -lim);
    }

    /* =================================================================
       THE POST-MORTEM — a lost run gets the board back for three seconds.

       Nothing about it is interactive: the rack is empty, the pulses are gone,
       and all that is left to do is show the player the thing the whole run was
       spent guessing at. The power slams back on, a scan climbs from the mouth
       row to the ceiling lighting every wall behind it, and then the corridor
       that was the way out draws itself from its door up to the gate. Only
       after that does the score land.
       ================================================================= */
    function startRecap() {
      phase = "recap"; recapT = 0; recapStep = 0; recapRow = 0;
      balls = [];                                  // nothing left to simulate
      Sound.clip("fail", 0.3);
      Overlay.vignette("rgba(255,45,120,.55)", 1, 900);
    }

    function updateRecap(dt) {
      var done, gx;
      recapT += dt;
      // 1. the beat of darkness is over: the grid is slammed back on and the
      //    scan starts climbing
      if (recapStep === 0 && recapT >= C.recapSurge) {
        recapStep = 1;
        Sound.clip("power", 0.9, 0.84);
        Fx.flash("#ffffff", 0.2); Fx.shake(9, 0.4);
        zapAll(0.9);
        Overlay.vignette(rgba(ARC, 0.5), 1, 1000);
      }
      // a click per row the scan crosses, climbing in pitch: the board is being
      // read back to the player one row at a time
      if (recapStep >= 1) {
        done = Math.floor(clamp((recapT - C.recapSurge) / C.recapSweep, 0, 1) * M.rows);
        while (recapRow < done) {
          recapRow++;
          Sound.clip("map", 0.2, 0.88 + recapRow * 0.07);
        }
      }
      // 2. the scan is at the ceiling: the whole maze is up, and the true
      //    corridor starts drawing itself out of its door
      if (recapStep === 1 && recapT >= C.recapSurge + C.recapSweep) {
        recapStep = 2;
        Sound.clip("deep", 0.3, 0.82);
      }
      // 3. it lands on the gate — the shot that was never fired
      if (recapStep === 2 && recapT >= C.recapSurge + C.recapSweep + C.recapTrace) {
        recapStep = 3;
        gateFlare = 1;
        gx = M.x0 + (exitCol + 0.5) * M.cw;
        Sound.clip("escape", 0.5, 1.08);
        Fx.ring(gx, M.y0, { from: 14, to: 210, color: EXIT_COL, width: 7, life: 0.55 });
        Fx.burst(gx, M.y0, { color: [EXIT_COL, "#ffffff"], count: 20, speed: 260,
                             life: 0.5, size: 5 });
      }
      if (recapT >= C.recapSeconds) finish();
    }

    /* THE STAR LADDER. The gate is what the run is about, so the stars are the
       gate and not the depth: a rack emptied into five dead ends is worth the
       points it mapped and nothing more.

         3  the way out, found with the fewest pulses a board can cost — which
            is also the maximum score that board can pay (see spareBonus). On a
            board whose crystal stands in a dead end that is TWO pulses, not
            one: the key is a whole shot and `shotPar` says so, so three stars
            still means "as cheap as this board can be" and never "impossible"
         2  the way out, found the long way
         1  no way out, but the point objective covered
         0  no way out and short of the objective

       The web build counts its own ladder (`levelTally`, below), and the gate
       is the whole of it: no score earns a star there. */
    function perfectRun() { return escaped && fired <= shotPar; }

    function starsEarned() {
      return perfectRun() ? 3 : escaped ? 2 : score >= C.parScore ? 1 : 0;
    }

    /* A LEVEL'S STARS ARE THE GATE AND THE PULSES IT COST, nothing else —
       the level layer's own count (`levelTally`), which replaces its score
       bands:

         3  a perfect read: out in `shotPar` pulses, the cheapest the board is
         2  out with one pulse more than that
         1  out, however many pulses it took — finding the gate is the level
         0  no way out, whatever the rack mapped on the way

       A rack spent reading the maze used to be worth a star for its points,
       and the gate found the long way two: one star is now the understanding
       of the board, and the other two are how cleanly it was read. */
    function levelTally() {
      if (!escaped) return 0;
      return perfectRun() ? 3 : fired <= shotPar + 1 ? 2 : 1;
    }
    function pulses(p) {
      return p === 1 ? Lang.t("Escape in <b>1</b> pulse")
                     : Lang.t("Escape in <b>{p}</b> pulses").replace("{p}", p);
    }

    /* The objectives card (a tap on the level pill), one row a star. */
    function levelRules() {
      return [Lang.t("Find the way out"), pulses(shotPar + 1), pulses(shotPar)];
    }

    function finish() {
      var stars = starsEarned();
      endRound({
        title: perfectRun() ? Lang.t("Perfect read!")
             : escaped ? Lang.t("Maze solved!")
             : deepest <= 1 ? Lang.t("So close!")
             : deepest <= M.rows / 3 ? Lang.t("Great run!") : C.copy.gameOver,
        variant: escaped ? "perfect" : deepest <= 1 ? "win" : "",
        score: score,
        stars: stars,
        rows: [
          // No row for the climb: the title already says how the run ended, and
          // "5 / 5" without an escape read as a win it was not — a pulse can
          // reach the top row and still never find the gap in the ceiling.
          // The rack is most of the score, so it is priced as the BONUS it is —
          // gold only when nothing was left on the table, which is one shot.
          { label: "Bonus", value: spare + (spare > 1 ? Lang.t(" pulses") : Lang.t(" pulse")),
            grade: escaped && spare >= C.startBalls - 1 ? "gold" : spare > 0 ? "accent" : "" },
          // A valve is a pulse that died in there: none of them is the clean run.
          { label: "Valves", value: valves.length,
            grade: valves.length === 0 ? "gold" : "" }
        ]
      });
    }

    /* --- the engine contract ------------------------------------------ */
    function reset() {
      var i;
      /* The band comes first: geometry() composites the backdrop out of it,
         and the scene the END SCREEN wears is the one just played. */
      BAND = bandFor();
      ARC = BAND.arc;
      Art.backdrop(BAND.scene);
      MOUTHS = C.cols / C.mouthW;
      geometry();
      generate();
      buildWalls();
      mouths = [];
      for (i = 0; i < MOUTHS; i++) mouths.push({ t: 1, seal: false, freed: false });
      valves = [];
      /* The band's furniture, in the order it depends on itself: the crystal
         was given a home by carve(), so it is put in px here; the bar it holds
         over the exit is a wall of the board like any other, welded shut and
         already `found` so it can never pay the map bonus; and the surge rolls
         the cycle this board will run. */
      placeCrystal();
      /* The ceiling is OPEN through the reveal and is shut by goDark() — see
         sealGates(). */
      lockWalls = []; lockFlare = 0;
      // Two pulses is what a board costs when the key is not on the way in.
      shotPar = C.perfectShots + (crystal && crystal.home === "maze" ? 1 : 0);
      rollSurge();
      rollSurgeNoise();
      surgeCrackle = 0;
      applySeal();
      phase = "reveal";
      balls = []; queue = C.startBalls; fired = 0; bounces = 0; mapped = 0;
      deepest = M.rows; escaped = false; spare = 0;
      recapT = 0; recapStep = 0; recapRow = 0;
      score = 0; clock = 0; revealT = 0; darkT = 0; endT = 0; recoil = 0;
      lastShot = -1; lastWall = -1; lastText = -1;
      jitterT = 0; gateFlare = 0;
      aimA = -Math.PI / 2; aiming = false; zaps = [];
      Sound.clip("power", 0.75);
      HUD.setScoreNow(0);
      refreshHUD();
      Fx.reset();
      /* THE BED. The band of the climb the level sits in names the stretch of
         the track the round rides, so replaying a level never restarts the
         music and crossing into the next band does. A playable has no level
         and a short cut of the track to play it on, so `null` — the whole of
         what this build ships — is the right section there. */
      Music.play(CONFIG.level ? BAND.music : null);
    }

    /* Five bands, and they are the map's OWN five: the level layer hands the
       game the same `d` it lerps the knobs with (docs/LEVELS.md), and the map
       names its cards off `min(4, floor(d * 5))`, so reading the band out of it
       is the only way a card that says Pressure is a board that plays it.
       Counting levels six at a time here looked like the same thing and is not
       — the map's `d` is a curve over a forking road, not a division — which
       put the rule and the card it is announced on a level apart at two of the
       four seams. A playable, and the endless run above level 30, have no `d`
       and ride the first band. */
    var LEVEL_D = null;
    function applyLevel(d) { LEVEL_D = (d == null) ? null : d; }
    function bandFor() {
      var b = C.bands;
      if (LEVEL_D == null || !CONFIG.level) return b[0];
      return b[clamp(Math.floor(LEVEL_D * 5), 0, b.length - 1)];
    }

    function onDown(p) {
      if (phase === "reveal") { skipReveal(); return; }
      if (phase !== "play") return;
      aiming = true; aimAt(p);
    }
    function onMove(p) { if (phase === "play" && aiming) aimAt(p); }
    function onUp(p) {
      if (phase !== "play" || !aiming) return;
      aiming = false; aimAt(p); fire();
    }

    function update(dt) {
      var i, s, sub, h, live, w;
      clock += dt;
      updateZaps(dt);
      if (recoil > 0) recoil = Math.max(0, recoil - dt * 5);
      if (gateFlare > 0) gateFlare = Math.max(0, gateFlare - dt * 1.4);

      // the arcs cooling down, and one shared jitter roll for the whole grid
      jitterT -= dt;
      if (jitterT <= 0) { rollSegs(); jitterT = 0.07; }
      for (i = 0; i < walls.length; i++) {
        w = walls[i];
        if (w.lit > 0) w.lit = Math.max(0, w.lit - dt / C.echoFade);
      }
      for (i = 0; i < MOUTHS; i++)
        if (mouths[i].t < 1) mouths[i].t = Math.min(1, mouths[i].t + dt / C.flapTime);
      for (i = 0; i < valves.length; i++)
        if (valves[i].swing < 1) valves[i].swing = Math.min(1, valves[i].swing + dt / C.flapTime);

      for (i = 0; i < decoys.length; i++)
        if (decoys[i].burn > 0) decoys[i].burn = Math.max(0, decoys[i].burn - dt * 1.4);
      if (lockFlare > 0) lockFlare = Math.max(0, lockFlare - dt * 1.6);

      if (phase === "reveal") {
        revealT += dt;
        if (revealT >= C.revealSeconds) goDark();
        return;
      }
      if (phase === "recap") { updateRecap(dt); return; }
      if (phase === "over") { endT += dt; if (endT > 1.1) finish(); return; }

      darkT += dt;
      stepSurge(dt);

      // Sub-stepped so a 700 px/s pulse never tunnels through a 10 px wall.
      sub = Math.ceil(C.ballSpeed * dt / C.subDiv);
      if (sub > 24) sub = 24; if (sub < 1) sub = 1;
      h = dt / sub;
      for (s = 0; s < sub && phase === "play"; s++)
        for (i = 0; i < balls.length; i++) if (balls[i].alive) stepBall(balls[i], h);

      live = 0;
      for (i = balls.length - 1; i >= 0; i--) {
        if (!balls[i].alive) { balls.splice(i, 1); continue; }
        balls[i].life -= dt;
        if (balls[i].life <= 0) { fizzle(balls[i]); balls.splice(i, 1); continue; }
        live++;
      }
      // Out of pulses and nothing left in flight: the run is lost, so the board
      // is handed back to the player for three seconds before the score lands.
      if (phase === "play" && !live && queue <= 0) startRecap();
    }

    /* =================================================================
       DRAWING

       An arc is a jittered polyline stroked in a few passes, from a wide dim
       halo down to a white-hot core (shadowBlur is banned in frame). The trick
       that keeps a 90-segment grid cheap is BATCHING: every wall in a group
       shares one colour and one alpha, so a whole group is one path and one
       stroke per pass. Only the handful of walls actually crackling right now
       are drawn on their own.
       ================================================================= */
    // 3 passes: halo, body, core. Widths are scaled by the group's weight. The
    // core is as thick as the bar the physics actually uses, so a lit wall reads
    // as a bar and not as a hairline.
    var PASSES = [[26, 0.09], [13, 0.22], [4.4, 0.92]];

    function pathWall(w, amp) {
      var dx = w.x1 - w.x0, dy = w.y1 - w.y0;
      var len = Math.sqrt(dx * dx + dy * dy) || 1;
      var nx = -dy / len, ny = dx / len, i, u, o;
      ctx.moveTo(w.x0, w.y0);
      for (i = 1; i <= 4; i++) {
        u = i / 5; o = w.seg[i] * amp;
        ctx.lineTo(w.x0 + dx * u + nx * o, w.y0 + dy * u + ny * o);
      }
      ctx.lineTo(w.x1, w.y1);
    }

    // One group, one stroke per pass. `pick` decides membership.
    function batch(pick, col, weight, amp, passes) {
      var q, i, w, drew;
      for (q = PASSES.length - passes; q < PASSES.length; q++) {
        ctx.beginPath();
        drew = false;
        for (i = 0; i < walls.length; i++) {
          w = walls[i];
          if (!w.solid || !pick(w)) continue;
          pathWall(w, amp);
          drew = true;
        }
        if (!drew) return;
        ctx.strokeStyle = rgba(col, PASSES[q][1] * weight);
        ctx.lineWidth = PASSES[q][0] * (0.5 + 0.5 * weight);
        ctx.stroke();
      }
    }

    /* A wall is on screen only while its own arc is burning down. The hot ones
       — struck in the last third of a second — are drawn individually, in four
       passes, because those are the ones the player is actually reading. The
       long dim tail is bucketed into a handful of brightness bands so a whole
       band is one path and one stroke per pass: with six pulses rattling
       through 42 px corridors there can be a hundred walls still glowing, and
       a hundred separate strokes a frame is not a budget this can afford. */
    var HOT = 0.86, BANDS = 5;

    function drawMaze() {
      var rev = revealLevel(), b;
      ctx.lineCap = "round"; ctx.lineJoin = "round";
      SCAN = recapFront();               // the post-mortem lights the grid in rows
      // 1. the whole grid, and the box around it, but only while the power is
      //    on — the opening reveal, and then the post-mortem of a lost run
      //    The labyrinth is the round's LAST element of the entrance (Enter),
      //    grid, box and doors in one piece: it is there to be memorised, so
      //    it lands whole once everything else stands, and the reveal's own
      //    clock only starts after it (the entrance holds the world).
      if (rev > 0.02 && Enter.begin(Layout.cx, (field.top + field.bottom) / 2, LAST)) {
        batch(isSolid, ARC, rev, 4 * rev, 3);
        // the walls the scan is crossing right now, struck white as it passes
        if (SCAN > -1e8) batch(isFresh, "#ffffff", 0.5, 8, 2);
        b = Math.max(field.top, Math.min(field.bottom, SCAN));
        ctx.strokeStyle = rgba(ARC, 0.75 * rev);
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.moveTo(field.left, b); ctx.lineTo(field.left, field.bottom);
        ctx.lineTo(field.right, field.bottom); ctx.lineTo(field.right, b);
        ctx.stroke();
        drawDoors(rev);
        Enter.end();
      }
      drawEchoes();
    }
    // 2. the dying echoes, in brightness bands, and 3. the few arcs still
    // cracking, each on its own
    function drawEchoes() {
      var i, w, b, lo, hi;
      for (b = 0; b < BANDS; b++) {
        lo = HOT * b / BANDS; hi = HOT * (b + 1) / BANDS;
        LO = lo; HI = hi;
        batch(inBand, ARC, 0.16 + 0.72 * (hi / HOT), 1.4 + 2 * (hi / HOT), 2);
      }
      // 3. and the few arcs still cracking, each on its own
      for (i = 0; i < walls.length; i++) {
        w = walls[i];
        if (w.solid && !w.lock && w.lit >= HOT) drawHotWall(w);
      }
    }
    var LO = 0, HI = 0;
    var LAST = { last: true };
    // How far the post-mortem's scan has climbed, and how deep its leading edge
    // is. SCAN is parked below the board whenever nothing is scanning, so the
    // opening reveal still draws the grid whole.
    var SCAN = -1e9, LEAD = 46;
    // A flap is a door, not a wall: it is left out of the grid batch and drawn
    // by drawDoors(), or the six ways in would read as six stretches of solid
    // floor during the only look the player ever gets at the board.
    function isSolid(w) { return !w.flap && !w.lock && (w.y0 + w.y1) / 2 >= SCAN; }
    function isFresh(w) {
      var y = (w.y0 + w.y1) / 2;
      return !w.flap && !w.lock && y >= SCAN && y <= SCAN + LEAD;
    }
    function inBand(w) { return w.lit > LO && w.lit <= HI; }

    /* The six doors, for the reveal only: a dashed sill instead of a bar, and a
       pair of chevrons standing in the throat. Dashed reads as "you can go
       through this", which is the single most important thing on the board. */
    function drawDoors(k) {
      var i, x0, x1, mid, j, w = C.mouthW * M.cw;
      ctx.save();
      ctx.setLineDash([13, 11]);
      ctx.lineCap = "butt";
      ctx.strokeStyle = rgba("#ffffff", 0.75 * k);
      ctx.lineWidth = 5;
      for (i = 0; i < MOUTHS; i++) {
        x0 = M.x0 + mouthCol(i) * M.cw; x1 = x0 + w;
        ctx.beginPath();
        ctx.moveTo(x0 + 6, M.y1); ctx.lineTo(x1 - 6, M.y1);
        ctx.stroke();
      }
      ctx.setLineDash([]);
      ctx.lineCap = "round";
      ctx.strokeStyle = rgba(ARC, 0.85 * k);
      for (i = 0; i < MOUTHS; i++) {
        mid = M.x0 + (mouthCol(i) + C.mouthW / 2) * M.cw;
        for (j = 0; j < 2; j++) {
          ctx.beginPath();
          ctx.moveTo(mid - 16, M.y1 - 14 - j * 15);
          ctx.lineTo(mid, M.y1 - 27 - j * 15);
          ctx.lineTo(mid + 16, M.y1 - 14 - j * 15);
          ctx.stroke();
        }
      }
      ctx.restore();
    }

    /* =================================================================
       THE POST-MORTEM, drawn.

       Two things on top of the re-lit grid: the scan crossing the arena, and
       then the corridor that was the way out, drawing itself from its door up
       to the gate. Both are gradients and polylines — no shadowBlur, same rule
       as everywhere else in here.
       ================================================================= */
    function drawScan() {
      var y = SCAN, g, h = 90;
      if (y < field.top - 6 || y > field.bottom + 6) return;
      g = ctx.createLinearGradient(0, y - h, 0, y + h);
      g.addColorStop(0, rgba(ARC, 0));
      g.addColorStop(0.5, rgba(ARC, 0.28));
      g.addColorStop(1, rgba(ARC, 0));
      ctx.fillStyle = g;
      ctx.fillRect(field.left, y - h, field.right - field.left, h * 2);
      ctx.strokeStyle = rgba("#eaffff", 0.9);
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(field.left, y); ctx.lineTo(field.right, y);
      ctx.stroke();
    }

    // The true corridor as a polyline in design space: out of the bay, up
    // through every cell of the carved path, and out through the ceiling.
    function truePoints() {
      var pts = [], i, k, r, c;
      if (!truePath || !truePath.length) return pts;
      pts.push({ x: M.x0 + (entryCol + 0.5) * M.cw, y: M.y1 + 34 });
      for (i = 0; i < truePath.length; i++) {
        k = truePath[i]; r = Math.floor(k / M.cols); c = k - r * M.cols;
        pts.push({ x: M.x0 + (c + 0.5) * M.cw, y: M.y0 + (r + 0.5) * M.ch });
      }
      pts.push({ x: M.x0 + (exitCol + 0.5) * M.cw, y: M.y0 - 44 });
      return pts;
    }

    var WAY_PASSES = [[24, 0.10], [12, 0.28], [4.5, 0.95]];

    function drawTrueWay() {
      var pts = truePoints(), p, total = 0, want, acc = 0, seg = [], head;
      var i, q, dx, dy, len, t, g, x0, w;
      if (pts.length < 2) return;
      p = (recapT - C.recapSurge - C.recapSweep) / C.recapTrace;
      if (p <= 0) return;
      p = clamp(p, 0, 1);
      p = p * p * (3 - 2 * p);

      // the door it was: the only one of the six that ever mattered
      x0 = M.x0 + mouthCol(entryMouth) * M.cw; w = C.mouthW * M.cw;
      g = ctx.createLinearGradient(0, M.y1 + 50, 0, M.y1 - 12);
      g.addColorStop(0, rgba(EXIT_COL, 0));
      g.addColorStop(1, rgba(EXIT_COL, 0.55));
      ctx.fillStyle = g;
      ctx.fillRect(x0, M.y1 - 12, w, 62);

      // how much of the corridor is drawn yet
      for (i = 1; i < pts.length; i++) {
        dx = pts[i].x - pts[i - 1].x; dy = pts[i].y - pts[i - 1].y;
        total += Math.sqrt(dx * dx + dy * dy);
      }
      want = total * p;
      seg.push(pts[0]);
      for (i = 1; i < pts.length; i++) {
        dx = pts[i].x - pts[i - 1].x; dy = pts[i].y - pts[i - 1].y;
        len = Math.sqrt(dx * dx + dy * dy) || 1;
        if (acc + len >= want) {
          t = (want - acc) / len;
          seg.push({ x: pts[i - 1].x + dx * t, y: pts[i - 1].y + dy * t });
          break;
        }
        acc += len; seg.push(pts[i]);
      }
      head = seg[seg.length - 1];

      ctx.lineCap = "round"; ctx.lineJoin = "round";
      for (q = 0; q < WAY_PASSES.length; q++) {
        ctx.strokeStyle = rgba(q === WAY_PASSES.length - 1 ? "#eaffee" : EXIT_COL,
                               WAY_PASSES[q][1]);
        ctx.lineWidth = WAY_PASSES[q][0];
        ctx.beginPath();
        ctx.moveTo(seg[0].x, seg[0].y);
        for (i = 1; i < seg.length; i++) ctx.lineTo(seg[i].x, seg[i].y);
        ctx.stroke();
      }
      // the head of the trace: the pulse that was never fired
      for (q = 3; q >= 0; q--) {
        ctx.fillStyle = rgba(q === 0 ? "#ffffff" : EXIT_COL, q === 0 ? 1 : 0.16);
        ctx.beginPath();
        ctx.arc(head.x, head.y, q === 0 ? 7 : 9 + q * 7, 0, TAU);
        ctx.fill();
      }
    }

    function drawHotWall(w) {
      var k = clamp(w.lit, 0, 1), flash = Math.pow(k, 0.6), q, mx, my;
      for (q = 0; q < ZAP_PASSES.length; q++) {
        ctx.beginPath();
        pathWall(w, 3 + 7 * k);
        ctx.strokeStyle = rgba(q === ZAP_PASSES.length - 1 ? "#ffffff" : ARC,
                               ZAP_PASSES[q][1] * flash);
        ctx.lineWidth = ZAP_PASSES[q][0] * (0.3 + 0.55 * k);
        ctx.stroke();
      }
      mx = (w.x0 + w.x1) / 2; my = (w.y0 + w.y1) / 2;
      ctx.globalAlpha = flash * 0.8;
      ctx.fillStyle = "#ffffff";
      ctx.beginPath(); ctx.arc(mx, my, 2 + 5 * k, 0, TAU); ctx.fill();
      ctx.globalAlpha = 1;
    }

    /* The six mouths, and the flap that shuts one of them. Each flap is two
       panels hinged on the teeth either side of the door: they swing up from
       hanging open to flat, and they stay lit, because a spent door is
       information the player needs for the rest of the run. */
    /* The six flaps. Shut, they draw nothing — like every other wall on this
       board, they exist only when something touches them. What is drawn is the
       swing: a pulse pushing through kicks the two panels wide and they drop
       back over flapTime, which is the one moment the player is told which door
       a shot actually took. */
    function drawMouths() {
      var i, k, x0, x1, half, a, w = C.mouthW * M.cw;
      ctx.lineCap = "round";
      ctx.lineWidth = C.wallT;
      for (i = 0; i < MOUTHS; i++) {
        k = clamp(mouths[i].t, 0, 1);
        if (k >= 1) continue;                      // shut and dark, like the rest
        x0 = M.x0 + mouthCol(i) * M.cw; x1 = x0 + w; half = w / 2;
        a = (1 - k) * Math.PI * 0.44;               // flat -> hanging wide open
        ctx.strokeStyle = rgba("#ffffff", 0.35 + 0.65 * (1 - k));
        ctx.beginPath();
        ctx.moveTo(x0, M.y1);
        ctx.lineTo(x0 + Math.cos(a) * half, M.y1 + Math.sin(a) * half);
        ctx.moveTo(x1, M.y1);
        ctx.lineTo(x1 - Math.cos(a) * half, M.y1 + Math.sin(a) * half);
        ctx.stroke();
      }
    }

    /* The valves the run forged. These are the ONE exception to the rule that
       nothing stays on screen: the player put them there, so the run is allowed
       to remember them — and it has to, because "which corridors only flow
       upward now" is the read the whole mechanic is about. Two panels hinged on
       the sides of the cell, swinging up the way a pulse pushes them, plus a
       chevron for the direction they let one through. Amber, so they never read
       as part of the cyan board. */
    function drawValves() {
      var i, w, k, half, a, mx, glow;
      ctx.lineCap = "round";
      for (i = 0; i < valves.length; i++) {
        w = valves[i];
        k = clamp(w.swing, 0, 1);
        half = (w.x1 - w.x0) / 2; mx = (w.x0 + w.x1) / 2;
        a = (1 - k) * Math.PI * 0.44;              // shut -> kicked wide open
        glow = 0.34 + 0.66 * (1 - k);
        ctx.lineWidth = C.wallT;
        ctx.strokeStyle = rgba(VALVE, glow);
        ctx.beginPath();
        ctx.moveTo(w.x0, w.y0);
        ctx.lineTo(w.x0 + Math.cos(a) * half, w.y0 - Math.sin(a) * half);
        ctx.moveTo(w.x1, w.y0);
        ctx.lineTo(w.x1 - Math.cos(a) * half, w.y0 - Math.sin(a) * half);
        ctx.stroke();
        ctx.lineWidth = 3;
        ctx.strokeStyle = rgba(VALVE, 0.28 + 0.4 * (1 - k));
        ctx.beginPath();
        ctx.moveTo(mx - 11, w.y0 - 20); ctx.lineTo(mx, w.y0 - 31); ctx.lineTo(mx + 11, w.y0 - 20);
        ctx.stroke();
      }
    }

    /* THE GATES. The exit is the one thing on the board lit from the first
       frame to the last, because it is what the player traces the path back
       from while the grid is still up — and on a band with false gates there
       are three of them, drawn by this same function and identical the moment
       the lights go out. The one tell is the HUM: through the reveal the true
       gate breathes hard, the false ones sit at a flat glow — and nothing is
       barred yet, because the crystal's bar only lands with the lights going
       out (see sealGates()).

       A gate a pulse burned out stays on screen, dark and welded shut: it is
       the run's own note, kept for the same reason the valves are. */
    function drawGates() {
      var i;
      var y = (Layout.top + 8 + M.y0) / 2;
      for (i = 0; i < decoys.length; i++) {
        if (!Enter.begin(M.x0 + (decoys[i].c + 0.5) * M.cw, y)) continue;
        drawGateAt(decoys[i].c, false, decoys[i]);
        Enter.end();
      }
      if (Enter.begin(M.x0 + (exitCol + 0.5) * M.cw, y)) {
        drawGateAt(exitCol, true, null);           // the real one last, on top
        Enter.end();
      }
    }

    function drawGateAt(col, real, d) {
      var gx0 = M.x0 + col * M.cw, gx1 = gx0 + M.cw;
      var top = Layout.top + 8, mid = (gx0 + gx1) / 2, i, g;
      var k = 0.62 + 0.38 * Math.sin(clock * 3), f = real ? clamp(gateFlare, 0, 1) : 0;
      /* THE TELL, and it is only ever on while the board is powered up: ONE
         beacon over the true gate, and nothing else anywhere. The three
         doorways are the same drawing at every moment of the round, this one
         included — putting the false ones out for the length of the reveal
         made them read as scenery instead of as gates, and a board where two
         of the three announce themselves as fakes is a board with one gate on
         it. So the difference is a thing that HAPPENS on the real one, not a
         thing the others lack, and it stops the moment the lights go out. */
      var tell = phase === "reveal" && decoys.length > 0;
      // The gate throbs ON the beacon's own beat — same clock, same phase — so
      // what the eye catches is one event with two halves and not a doorway
      // that is permanently a little brighter than its neighbours.
      var hum = (real && tell) ? 0.28 * (1 - beaconBeat()) * (1 - beaconBeat()) : 0;
      var dead = !!(d && d.dead), burn = d ? clamp(d.burn, 0, 1) : 0;
      var tint = dead ? "#6f7d94" : EXIT_COL, core = dead ? "#c9d6ea" : "#eaffee";
      var lit = dead ? 0.3 + 0.7 * burn : 1;
      if (dead) k = 0.5;

      // The doorway itself: light POURING OUT of the gap, brightest at the gap.
      // No lintel across the top — a bar there reads as a door that is shut.
      g = ctx.createLinearGradient(0, M.y0, 0, top - 6);
      g.addColorStop(0, rgba(tint, (0.30 * k + 0.55 * f + 0.22 * hum) * lit));
      g.addColorStop(1, rgba(tint, 0));
      ctx.fillStyle = g;
      ctx.fillRect(gx0 + C.wallT / 2, top - 6, M.cw - C.wallT, M.y0 - top + 6);

      // the two jambs, glowing outward from the gap
      ctx.lineCap = "round";
      for (i = 2; i >= 0; i--) {
        ctx.strokeStyle = rgba(i === 0 ? core : tint,
                               ((i === 0 ? 0.9 : 0.12 * (3 - i)) * (0.7 + 0.3 * k) +
                                f * 0.3 + hum * (i === 0 ? 0.1 : 0.16)) * lit);
        ctx.lineWidth = (i === 0 ? 5 : 7 + i * 8) * (1 + 0.22 * hum);
        ctx.beginPath();
        ctx.moveTo(gx0, M.y0 + 3); ctx.lineTo(gx0, top + 16);
        ctx.moveTo(gx1, M.y0 + 3); ctx.lineTo(gx1, top + 16);
        ctx.stroke();
      }

      // a burned gate is welded, and the weld is what says so
      if (dead) {
        ctx.strokeStyle = rgba("#8d9bb2", 0.5 + 0.5 * burn);
        ctx.lineWidth = C.wallT;
        ctx.beginPath(); ctx.moveTo(gx0 + 3, M.y0); ctx.lineTo(gx1 - 3, M.y0); ctx.stroke();
        return;
      }
      if (lockWalls.length) drawLock(gx0, gx1);

      // two chevrons climbing out of it, the brighter one leading
      for (i = 0; i < 2; i++) {
        ctx.globalAlpha = clamp(k - i * 0.3 + f + hum * 0.3, 0.15, 1);
        if (!Icon.draw(ctx, "icoExit", mid, top + 30 - i * 20, 34, core)) {
          ctx.strokeStyle = core; ctx.lineWidth = 4;
          ctx.beginPath();
          ctx.moveTo(mid - 14, top + 38 - i * 20);
          ctx.lineTo(mid, top + 24 - i * 20);
          ctx.lineTo(mid + 14, top + 38 - i * 20);
          ctx.stroke();
        }
      }
      ctx.globalAlpha = 1;
      ctx.fillStyle = rgba(core, 0.6 + 0.4 * k);
      ctx.font = "900 20px -apple-system,Segoe UI,Roboto,sans-serif";
      ctx.textAlign = "center"; ctx.textBaseline = "middle";
      ctx.fillText(upper(Lang.t("Exit")), mid, top - 1);
      if (tell && real) drawBeacon(mid, M.y0);
    }

    /* The beacon on the true gate, for the length of the reveal: two rings
       going out of the gap, half a beat apart, and a wash of green over the
       band the gate stands in. It is the loudest thing on a screen that is
       otherwise a grid of thin arcs, which is the point — what the player is
       being asked to keep is WHICH of three holes, and they have a second and a
       half to take it. */
    var BEACON_RATE = 1.1, BEACON_RINGS = 3;
    function beaconBeat() { return (clock * BEACON_RATE) % 1; }
    function drawBeacon(mx, my) {
      var i, t, r, a;
      ctx.save();
      ctx.lineCap = "round";
      for (i = 0; i < BEACON_RINGS; i++) {
        t = (beaconBeat() + i / BEACON_RINGS) % 1;
        // It stays inside the gate's own band: a ring that climbs past
        // Layout.top slides under the HUD, and half a ring is a smear. It
        // stops short of even that — the beacon has to be FOUND in a second
        // and a half, not seen from the back of the room, or the band stops
        // being a memory test.
        r = 10 + t * Math.max(18, C.gateH - 46);
        a = (1 - t) * (1 - t);
        // A GREEN ring is not enough on a green band: the hall this game is
        // played in changes colour every six levels and one of the five arcs
        // LIME, which a green halo simply joins. The core is white — the one
        // colour no band owns — and the halo is the gate's own, so the beacon
        // reads the same in all five.
        ctx.strokeStyle = rgba(EXIT_COL, a * 0.12);
        ctx.lineWidth = 3 + 3 * (1 - t);
        ctx.beginPath(); ctx.arc(mx, my, r, Math.PI, TAU);   // upward half only
        ctx.stroke();
        ctx.strokeStyle = rgba("#ffffff", a * 0.22);
        ctx.lineWidth = 1 + 1 * (1 - t);
        ctx.beginPath(); ctx.arc(mx, my, r, Math.PI, TAU);
        ctx.stroke();
      }
      ctx.restore();
    }

    /* The bar the crystal holds across the way out, drawn IN the gap and not
       over the jambs: what the player has to read is a door with something in
       it, never a door that was never there. The facets are the crystal's own,
       which is what pairs the two without spending a second colour on it. */
    function drawLock(gx0, gx1) {
      var y = M.y0, f = clamp(lockFlare, 0, 1), i, x;
      var a = clamp(0.55 + 0.2 * Math.sin(clock * 4) + 0.45 * f, 0, 1);
      ctx.lineCap = "round";
      ctx.strokeStyle = rgba(CRYSTAL, a * 0.28);
      ctx.lineWidth = C.wallT + 14;
      ctx.beginPath(); ctx.moveTo(gx0 + 5, y); ctx.lineTo(gx1 - 5, y); ctx.stroke();
      ctx.strokeStyle = rgba(CRYSTAL, a);
      ctx.lineWidth = C.wallT;
      ctx.beginPath(); ctx.moveTo(gx0 + 5, y); ctx.lineTo(gx1 - 5, y); ctx.stroke();
      ctx.strokeStyle = rgba("#ffffff", a * 0.55);
      ctx.lineWidth = 2;
      for (i = 1; i <= 3; i++) {
        x = gx0 + (gx1 - gx0) * i / 4;
        ctx.beginPath(); ctx.moveTo(x - 5, y - 7); ctx.lineTo(x + 5, y + 7); ctx.stroke();
      }
    }

    /* THE CRYSTAL. The one object in this game lit in the dark from the first
       frame to the last: a locked board with an invisible key would be a board
       with no way out, and a key that only showed on an echo would be a board
       won by luck. A tall six-sided gem with a white core and a slow breath, so
       it never reads as a piece of the grid. */
    function crystalPath(x, y, r, scale) {
      var i, a, px, py;
      ctx.beginPath();
      for (i = 0; i < 6; i++) {
        a = -Math.PI / 2 + i * TAU / 6;
        px = x + Math.cos(a) * r * scale * 0.82;
        py = y + Math.sin(a) * r * scale * 1.14;
        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.closePath();
    }
    function drawCrystal() {
      if (!crystal || !crystal.alive) return;
      if (!Enter.begin(crystal.x, crystal.y)) return;
      drawGem(crystal.x, crystal.y, crystal.r);
      Enter.end();
    }
    function drawGem(x, y, r) {
      var k = 0.72 + 0.28 * Math.sin(clock * 2.6);
      ctx.save();
      ctx.lineJoin = "round";
      ctx.fillStyle = rgba(CRYSTAL, 0.12 * k);
      ctx.beginPath(); ctx.arc(x, y, r * 2.3, 0, TAU); ctx.fill();
      ctx.fillStyle = rgba(CRYSTAL, 0.2 * k);
      ctx.beginPath(); ctx.arc(x, y, r * 1.5, 0, TAU); ctx.fill();
      crystalPath(x, y, r, 1);
      ctx.fillStyle = rgba(CRYSTAL, 0.88);
      ctx.fill();
      ctx.strokeStyle = rgba("#ffd2f4", 0.85 + 0.15 * k);
      ctx.lineWidth = 2.5; ctx.stroke();
      crystalPath(x, y, r, 0.44);
      ctx.fillStyle = rgba("#ffffff", 0.7 + 0.3 * k);
      ctx.fill();
      ctx.restore();
    }

    /* THE FENCE. One live wire along the whole mouth row with a single GAP in
       it, and the gap is what moves. It is drawn at a low burn the whole round
       and struck white for a moment at every jump, which is the beat made
       visible — the player has to see where the gap IS, because what the
       mechanic asks is where it will BE by the time a pulse gets up there.

       Two runs of jittered polyline, left of the gap and right of it, and the
       gap's own two posts. The curtain hanging under the wire is what makes it
       read as a barrier from the cannon, 400 px below.  */
    var SURGE_SEGS = 26;
    var SURGE_PASSES = [[30, 0.1], [15, 0.26], [6, 0.8]];
    function rollSurgeNoise() {
      var i;
      if (!surgeNoise) surgeNoise = [];
      surgeNoise.length = 0;
      for (i = 0; i <= SURGE_SEGS; i++) surgeNoise.push(Rand.range(-1, 1));
    }
    // One run of wire, between two x. The noise is sampled off the SCREEN
    // position and not off the run, so a run keeps its shape when the gap moves
    // through it instead of rippling from end to end every beat.
    function fenceRun(xa, xb, k) {
      var span = field.right - field.left, i, n, u, x, y, o;
      if (xb - xa < 2) return;
      n = Math.max(2, Math.round((xb - xa) / span * SURGE_SEGS));
      ctx.beginPath();
      for (i = 0; i <= n; i++) {
        x = xa + (xb - xa) * (i / n);
        u = (x - field.left) / span * SURGE_SEGS;
        o = (surgeNoise[Math.round(u)] || 0) * (3 + 7 * k);
        y = M.y1 + o;
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
    /* THE GAP: two posts and a breath of light standing in the hole. It is the
       one thing on this board that says "through here, now", so it is lit
       whether the fence has just jumped or not. Radial, because a rectangle of
       light has edges and those edges read as an object rather than a glow.

       A door the fence BURNT OUT on is the same hole at a standstill: it never
       takes the white strike, and its posts are the fence's colour instead of
       white, so a permanent opening cannot be mistaken for the one that moves. */
    function drawGap(gx0, gx1, k, dead) {
      var m = (gx0 + gx1) / 2, w = gx1 - gx0, g;
      g = ctx.createRadialGradient(m, M.y1, 2, m, M.y1, w * 0.8);
      g.addColorStop(0, rgba("#ffffff", dead ? 0.12 : 0.3 + 0.2 * k));
      // the pulse's own colour, not the fence's: the hole belongs to what goes
      // through it
      g.addColorStop(0.4, rgba(PULSE.core, dead ? 0.1 : 0.16 + 0.12 * k));
      g.addColorStop(1, rgba(PULSE.core, 0));
      ctx.fillStyle = g;
      ctx.fillRect(gx0 - w * 0.4, M.y1 - w * 0.8, w * 1.8, w * 1.6);
      ctx.fillStyle = dead ? rgba(SURGE, 0.5) : rgba("#ffffff", 0.75 + 0.25 * k);
      ctx.beginPath(); ctx.arc(gx0, M.y1, dead ? 4 : 5, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(gx1, M.y1, dead ? 4 : 5, 0, TAU); ctx.fill();
      ctx.fillStyle = rgba(SURGE, dead ? 0.16 : 0.35 + 0.3 * k);
      ctx.beginPath(); ctx.arc(gx0, M.y1, dead ? 9 : 12, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(gx1, M.y1, dead ? 9 : 12, 0, TAU); ctx.fill();
    }
    /* The row is walked door by door rather than cut once around the moving
       gap: after a burn-out there are several holes in the wire, and the live
       one is only one of them. Every closed door is one length of wire and one
       length of curtain; every open one is a hole the run stops at. */
    function drawSurge() {
      var i, k, q, g, x0, x1, run, open = [], seq = [];
      if (!surgeSeq || !surgeSeq.length || phase !== "play") return;
      k = clamp(surgeFlash / C.surgeFlash, 0, 1);
      for (i = 0; i < MOUTHS; i++) {
        if (mouths[i].seal) continue;
        x0 = M.x0 + mouthCol(i) * M.cw;
        open.push([x0, x0 + C.mouthW * M.cw, i !== surgeSeq[surgeI]]);
      }
      // the stretches of live wire, between the holes
      x0 = field.left;
      for (i = 0; i <= open.length; i++) {
        x1 = i < open.length ? open[i][0] : field.right;
        if (x1 > x0) seq.push([x0, x1]);
        if (i < open.length) x0 = open[i][1];
      }
      ctx.save();
      ctx.lineCap = "round"; ctx.lineJoin = "round";
      // the curtain, under the live stretches only
      g = ctx.createLinearGradient(0, M.y1, 0, M.y1 + 46);
      g.addColorStop(0, rgba(SURGE, 0.16 + 0.26 * k));
      g.addColorStop(1, rgba(SURGE, 0));
      ctx.fillStyle = g;
      for (i = 0; i < seq.length; i++) {
        run = seq[i];
        ctx.fillRect(run[0], M.y1, run[1] - run[0], 46);
      }
      for (q = 0; q < SURGE_PASSES.length; q++) {
        ctx.strokeStyle = rgba(q === SURGE_PASSES.length - 1 ? "#ffffff" : SURGE,
                               SURGE_PASSES[q][1] * (0.26 + 0.74 * k));
        ctx.lineWidth = SURGE_PASSES[q][0] * (0.5 + 0.5 * k);
        for (i = 0; i < seq.length; i++) fenceRun(seq[i][0], seq[i][1], k);
      }
      for (i = 0; i < open.length; i++) drawGap(open[i][0], open[i][1], k, open[i][2]);
      ctx.restore();
    }

    // The arena's own edges: a dim line so the box always reads, with the zaps
    // drawn on top of it.
    /* The arena has no painted frame at all — same rule as the maze, and the
       same rule as the fence in games/bouncetry: the two sides and the floor
       are drawn ONLY where and when a pulse has just struck one. */
    function drawArena() {
      for (var i = 0; i < zaps.length; i++) drawZap(zaps[i]);
    }

    /* The sight is deliberately short and straight: it stops at the mouth row.
       Solving the bounces inside would hand the player the maze, which is the
       one thing this game is about not giving away. */
    function drawAim() {
      var mx = cannon.x + Math.cos(aimA) * C.muzzle;
      var my = cannon.y + Math.sin(aimA) * C.muzzle;
      var sx = Math.cos(aimA), sy = Math.sin(aimA);
      var L = C.aimBeam, t, i, n, x, y;
      if (sy < -0.001) L = Math.min(L, Math.max(0, (M.y1 - my) / sy));
      n = Math.floor(L / 22);
      for (i = 0; i < n; i++) {
        t = i * 22 + 8;
        x = mx + sx * t; y = my + sy * t;
        ctx.globalAlpha = clamp(0.85 - i / n * 0.6, 0.15, 0.85);
        ctx.fillStyle = PULSE.core;
        ctx.beginPath(); ctx.arc(x, y, 4.5 - 1.6 * (i / n), 0, TAU); ctx.fill();
      }
      ctx.globalAlpha = 1;
      if (queue > 0) {
        ctx.strokeStyle = rgba(PULSE.light, 0.8); ctx.lineWidth = 2.5;
        ctx.beginPath(); ctx.arc(mx + sx * L, my + sy * L, 11, 0, TAU); ctx.stroke();
      }
    }

    /* The cannon: a pylon on the arena floor, a deck carrying the magazine, and
       a barrel that swings with the aim, recoils on the shot and holds a
       charged pulse in its throat. Flat fills and rings only. */
    function drawCannon() {
      var x = cannon.x, y = cannon.y, g, i, a, dx, k, bay;

      ctx.fillStyle = "#080e22";
      ctx.beginPath();
      ctx.moveTo(x - 30, y + 16); ctx.lineTo(x + 30, y + 16);
      ctx.lineTo(x + 50, field.bottom); ctx.lineTo(x - 50, field.bottom);
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = rgba(ARC, 0.28);
      ctx.fillRect(x - 17, y + 26, 5, field.bottom - y - 26);
      ctx.fillRect(x + 12, y + 26, 5, field.bottom - y - 26);
      g = ctx.createLinearGradient(0, field.bottom - 20, 0, field.bottom + 4);
      g.addColorStop(0, "#2c3c66"); g.addColorStop(1, "#0c1228");
      ctx.fillStyle = g; rr(ctx, x - 62, field.bottom - 20, 124, 22, 8); ctx.fill();

      // the barrel, authored pointing up and swung onto the aim
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(aimA + Math.PI / 2);
      ctx.translate(0, recoil * 14);
      ctx.fillStyle = "rgba(5,9,24,.55)";
      rr(ctx, -26, -34, 52, 52, 14); ctx.fill();
      g = ctx.createLinearGradient(-22, 0, 22, 0);
      g.addColorStop(0, "#0c1426"); g.addColorStop(0.3, "#5f7ba8");
      g.addColorStop(0.52, "#a9c8ea"); g.addColorStop(0.78, "#33456c"); g.addColorStop(1, "#0f1628");
      ctx.fillStyle = g; rr(ctx, -20, -92, 40, 110, 13); ctx.fill();
      ctx.strokeStyle = "rgba(7,11,26,.85)"; ctx.lineWidth = 3;
      rr(ctx, -20, -92, 40, 110, 13); ctx.stroke();
      ctx.fillStyle = "rgba(255,255,255,.28)";
      rr(ctx, -13, -84, 6, 92, 3); ctx.fill();
      ctx.fillStyle = rgba(PULSE.core, queue > 0 ? 0.9 : 0.25);
      rr(ctx, -22, -62, 44, 8, 4); ctx.fill();
      rr(ctx, -22, -42, 44, 8, 4); ctx.fill();
      rr(ctx, -22, -22, 44, 8, 4); ctx.fill();
      g = ctx.createLinearGradient(-27, 0, 27, 0);
      g.addColorStop(0, "#16203a"); g.addColorStop(0.48, "#d4e8ff"); g.addColorStop(1, "#16203a");
      ctx.fillStyle = g; rr(ctx, -26, -110, 52, 26, 9); ctx.fill();
      ctx.strokeStyle = "rgba(7,11,26,.8)"; ctx.lineWidth = 3;
      rr(ctx, -26, -110, 52, 26, 9); ctx.stroke();
      ctx.fillStyle = "#03060f"; rr(ctx, -13, -106, 26, 19, 6); ctx.fill();
      k = queue > 0 ? 0.55 + 0.45 * Math.sin(clock * 5) : 0;
      for (i = 3; i >= 1; i--) {
        ctx.fillStyle = rgba(PULSE.core, 0.15 * i * k);
        ctx.beginPath(); ctx.arc(0, -97, 6 + i * 6, 0, TAU); ctx.fill();
      }
      if (queue > 0) {
        ctx.fillStyle = rgba(PULSE.light, 0.5 + 0.5 * k);
        ctx.beginPath(); ctx.arc(0, -97, 7.5, 0, TAU); ctx.fill();
      }
      ctx.restore();

      // the shoulder the barrel turns in, over the tube's tail
      g = ctx.createLinearGradient(0, y - 36, 0, y + 18);
      g.addColorStop(0, "#a9c8ea"); g.addColorStop(0.5, "#334768"); g.addColorStop(1, "#111a2f");
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(x, y, 36, Math.PI, TAU); ctx.closePath(); ctx.fill();
      ctx.fillRect(x - 36, y, 72, 10);
      ctx.strokeStyle = rgba(PULSE.core, 0.7); ctx.lineWidth = 4;
      ctx.beginPath(); ctx.arc(x, y, 36, Math.PI, TAU); ctx.stroke();
      ctx.strokeStyle = "rgba(7,11,26,.7)"; ctx.lineWidth = 3;
      for (i = 0; i <= 8; i++) {
        a = Math.PI + i * Math.PI / 8;
        ctx.beginPath();
        ctx.moveTo(x + Math.cos(a) * 27, y + Math.sin(a) * 27);
        ctx.lineTo(x + Math.cos(a) * 35, y + Math.sin(a) * 35);
        ctx.stroke();
      }

      /* the deck and its magazine, drawn LAST: the base has to hide the pivot,
         or the barrel's tail shows through it mid-swing. One bead per pulse
         still in the rack. */
      g = ctx.createLinearGradient(0, y + 2, 0, y + 40);
      g.addColorStop(0, "#5f78b5"); g.addColorStop(0.45, "#31446c"); g.addColorStop(1, "#10182c");
      ctx.fillStyle = g; rr(ctx, x - 80, y + 2, 160, 38, 13); ctx.fill();
      ctx.strokeStyle = "rgba(7,11,26,.7)"; ctx.lineWidth = 3;
      rr(ctx, x - 80, y + 2, 160, 38, 13); ctx.stroke();
      ctx.fillStyle = "rgba(255,255,255,.15)"; rr(ctx, x - 72, y + 6, 144, 7, 4); ctx.fill();
      bay = C.startBalls;
      ctx.fillStyle = "rgba(3,7,20,.75)";
      rr(ctx, x - bay * 9 - 7, y + 18, bay * 18 + 14, 18, 9); ctx.fill();
      for (i = 0; i < bay; i++) {
        dx = x + (i - (bay - 1) / 2) * 18;
        if (i < queue) {
          ctx.fillStyle = rgba(PULSE.core, 0.35);
          ctx.beginPath(); ctx.arc(dx, y + 27, 8, 0, TAU); ctx.fill();
          ctx.fillStyle = PULSE.core;
          ctx.beginPath(); ctx.arc(dx, y + 27, 5.6, 0, TAU); ctx.fill();
          ctx.fillStyle = rgba(PULSE.light, 0.9);
          ctx.beginPath(); ctx.arc(dx - 1.7, y + 25.4, 2.3, 0, TAU); ctx.fill();
        } else {
          ctx.strokeStyle = "rgba(126,249,255,.22)"; ctx.lineWidth = 2;
          ctx.beginPath(); ctx.arc(dx, y + 27, 5.6, 0, TAU); ctx.stroke();
        }
      }
    }

    /* A pulse is a comet with a charge gauge wrapped round it: the ring closes
       as its life runs out and the whole thing bleeds toward the danger colour,
       so "this one is nearly spent" is readable at a glance. */
    function drawBalls() {
      var i, b, sp, k, col, R = C.ballR, warn;
      ctx.lineCap = "round";
      for (i = 0; i < balls.length; i++) {
        b = balls[i]; if (!b.alive) continue;
        k = clamp(b.life / C.ballLife, 0, 1);
        col = mix(DYING, PULSE.core, Math.min(1, k / 0.45));
        warn = k < 0.22 ? 0.55 + 0.45 * Math.sin(clock * 18) : 1;
        sp = Math.sqrt(b.vx * b.vx + b.vy * b.vy) || 1;
        ctx.strokeStyle = rgba(PULSE.core, 0.26 * k + 0.06);
        ctx.lineWidth = R * 1.3;
        ctx.beginPath();
        ctx.moveTo(b.x - b.vx / sp * 46, b.y - b.vy / sp * 46); ctx.lineTo(b.x, b.y);
        ctx.stroke();
        ctx.fillStyle = col;
        ctx.globalAlpha = warn * 0.24;
        ctx.beginPath(); ctx.arc(b.x, b.y, R * 1.9, 0, TAU); ctx.fill();
        ctx.globalAlpha = warn;
        ctx.beginPath(); ctx.arc(b.x, b.y, R, 0, TAU); ctx.fill();
        ctx.fillStyle = PULSE.light;
        ctx.beginPath(); ctx.arc(b.x - R * 0.28, b.y - R * 0.3, R * 0.45, 0, TAU); ctx.fill();
        // the charge gauge
        ctx.strokeStyle = col; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(b.x, b.y, R + 7, -Math.PI / 2, -Math.PI / 2 + TAU * k); ctx.stroke();
        ctx.globalAlpha = 1;
      }
    }

    /* The reveal has to be a countdown or it is just a flash: a single shrinking
       bar in the launch bay, wordless, so the grid the player is trying to read
       is never covered and nothing has to be parsed while the clock runs. */
    function drawRevealHud(spent, total) {
      var t = clamp(1 - spent / total, 0, 1);
      var w = 360, x = Layout.cx - w / 2, y = M.y1 + 40;
      ctx.fillStyle = "rgba(5,9,26,.7)"; rr(ctx, x, y + 24, w, 14, 7); ctx.fill();
      ctx.fillStyle = ARC; rr(ctx, x + 2, y + 26, (w - 4) * t, 10, 5); ctx.fill();
    }

    function render() {
      if (bgCv) ctx.drawImage(bgCv, 0, 0, view.w, view.h);
      else { ctx.fillStyle = C.bg; ctx.fillRect(0, 0, view.w, view.h); }
      drawGates();     // the way out, and the band's false ones
      drawMaze();      // only what is still lit
      drawValves();    // and the valves the run built, which do stay
      drawCrystal();   // and the key, which is lit the whole way through
      drawMouths();    // only a flap still swinging
      drawSurge();     // the fence, and the one gap in it
      drawArena();     // only where the frame was just struck
      if (phase === "play") drawAim();
      if (Enter.begin(cannon.x, cannon.y)) { drawCannon(); Enter.end(); }
      drawBalls();
      if (phase === "reveal" && Enter.begin(Layout.cx, M.y1 + 71)) {
        drawRevealHud(revealT, C.revealSeconds);
        Enter.end();
      }
      if (phase === "recap") { drawScan(); drawTrueWay(); }
    }

    /* =================================================================
       THE GUIDE — every rule, as pages (packages/webshell/guide.js).

       A page SHOWS before it tells, and every picture here is painted by the
       round's OWN renderer: the round's `ctx` is lent to a canvas of the
       picture's own (paintPic), and so is everything the draw functions read
       — the board, the field, the gates, the fence — for the length of one
       synchronous call (scene). A small board is carved for it by carve()
       itself, so the maze in the guide is a maze this game deals, and the
       round's own state is put back untouched however the picture went. The
       guide may open before any round (the Help card on the title screen),
       when none of that state exists yet: a picture never reads it, it only
       sets its own and gives the old one back.

       A page's `lv` is the first level whose band deals the idea — read off
       the map's own curve, which is what bandFor() reads too: band 2 first
       at level 4, band 3 at 10 (its crystal in a dead end from 11), band 4
       at 18, band 5 at 23. Locked in the contents until then.
       ================================================================= */
    function paintPic(W, H, fn) {
      var cv = document.createElement("canvas"), k = view.dpr || 1, keep = ctx;
      cv.width = Math.round(W * k); cv.height = Math.round(H * k);
      cv.style.width = W + "px"; cv.style.height = H + "px";
      ctx = cv.getContext("2d"); ctx.scale(k, k);
      try { fn(); } finally { ctx = keep; }
      return cv;
    }

    /* Everything a draw function reads, taken and given back as one. */
    function borrow() {
      return { ARC: ARC, BAND: BAND, field: field, M: M, cannon: cannon, MOUTHS: MOUTHS,
               hSolid: hSolid, vSolid: vSolid, mainCell: mainCell, entryMouth: entryMouth,
               entryCol: entryCol, exitCol: exitCol, decoys: decoys, crystal: crystal,
               lockWalls: lockWalls, lockFlare: lockFlare, surgeSeq: surgeSeq, surgeI: surgeI,
               surgeFlash: surgeFlash, surgeNoise: surgeNoise, walls: walls, hw: hw, vw: vw,
               wallCount: wallCount, mouths: mouths, phase: phase, valves: valves, balls: balls,
               queue: queue, truePath: truePath, recapT: recapT, clock: clock, recoil: recoil,
               gateFlare: gateFlare, aimA: aimA, zaps: zaps, SCAN: SCAN, LO: LO, HI: HI };
    }
    function giveBack(s) {
      ARC = s.ARC; BAND = s.BAND; field = s.field; M = s.M; cannon = s.cannon; MOUTHS = s.MOUTHS;
      hSolid = s.hSolid; vSolid = s.vSolid; mainCell = s.mainCell; entryMouth = s.entryMouth;
      entryCol = s.entryCol; exitCol = s.exitCol; decoys = s.decoys; crystal = s.crystal;
      lockWalls = s.lockWalls; lockFlare = s.lockFlare; surgeSeq = s.surgeSeq; surgeI = s.surgeI;
      surgeFlash = s.surgeFlash; surgeNoise = s.surgeNoise; walls = s.walls; hw = s.hw; vw = s.vw;
      wallCount = s.wallCount; mouths = s.mouths; phase = s.phase; valves = s.valves; balls = s.balls;
      queue = s.queue; truePath = s.truePath; recapT = s.recapT; clock = s.clock; recoil = s.recoil;
      gateFlare = s.gateFlare; aimA = s.aimA; zaps = s.zaps; SCAN = s.SCAN; LO = s.LO; HI = s.HI;
    }

    /* The gate band is drawn under `Layout.top` (drawGateAt), so a picture is
       painted in a frame shifted by OY: picture y `p` is design y `OY + p`,
       and the gates' top edge lands at picture y GT. */
    var OY = 0, GT = 22;
    function gateFloor() { return GT + C.gateH - 8; }   // where the maze hangs

    function scene(W, H, band, fn) {
      return paintPic(W, H, function () {
        var keep = borrow();
        try {
          BAND = band || C.bands[0]; ARC = BAND.arc;
          phase = "play"; clock = 0.35; recoil = 0; gateFlare = 0; lockFlare = 0;
          balls = []; valves = []; zaps = []; decoys = []; lockWalls = []; crystal = null;
          surgeSeq = []; surgeI = 0; surgeFlash = 0; surgeNoise = null; SCAN = -1e9;
          truePath = []; recapT = 0; queue = 0; aimA = -Math.PI / 2; mouths = [];
          hall(W, H, band);
          OY = (typeof Layout !== "undefined" && Layout.top) ? Layout.top + 8 - GT : 8 - GT;
          ctx.translate(0, -OY);
          fn(W, H);
        } finally { giveBack(keep); }
      });
    }
    // The band's painted hall under its own scrim, as buildBackdrop() lays it.
    function hall(W, H, band) {
      var img = band && typeof ArtImages !== "undefined" && ArtImages[band.scene], s, w, h;
      ctx.fillStyle = C.bg; ctx.fillRect(0, 0, W, H);
      if (!img || !img.width) return;
      s = Math.max(W / img.width, H / img.height);
      w = img.width * s; h = img.height * s;
      ctx.drawImage(img, (W - w) / 2, (H - h) / 2, w, h);
      ctx.fillStyle = rgba("#04060f", band.scrim);
      ctx.fillRect(0, 0, W, H);
    }
    /* A real board, carved by carve() at the picture's size: `o.y0` is the
       picture y of its ceiling, `o.bay` how deep the launch bay runs under it,
       and `o.decoys` / `o.crystal` the furniture a band would give it. */
    function board(o) {
      var keepBand = BAND, t, m, ok, want = o.decoys || 0;
      M = { cols: o.cols, rows: o.rows, cw: o.cw, ch: o.ch, x0: o.x0, y0: OY + o.y0, y1: 0 };
      M.y1 = M.y0 + M.ch * M.rows;
      field = { left: o.x0, right: o.x0 + o.cols * o.cw, top: M.y0, bottom: M.y1 + (o.bay || 0) };
      cannon = { x: (field.left + field.right) / 2, y: field.bottom - C.cannonH };
      MOUTHS = Math.floor(o.cols / C.mouthW);
      BAND = { decoys: want, crystal: o.crystal || "" };
      try {
        for (t = 0; t < 24; t++) {
          carve();
          for (ok = 0, m = 0; m < MOUTHS; m++) if (reaches(m)) ok++;
          if (ok === 1 && decoys.length >= want) break;
        }
      } finally { BAND = keepBand; }
      traceTruePath();
      buildWalls();
      placeCrystal();
      mouths = [];
      for (m = 0; m < MOUTHS; m++) mouths.push({ t: 1, seal: false, freed: false });
      lockWalls = [];
    }
    function grid(k) { batch(isSolid, ARC, k, 4 * k, 3); }
    function cellXY(k) {
      var r = Math.floor(k / M.cols), c = k - r * M.cols;
      return { r: r, c: c, x: M.x0 + (c + 0.5) * M.cw, y: M.y0 + (r + 0.5) * M.ch };
    }
    // The walls of one cell, struck: what an echo leaves behind it.
    function strike(k, lit) {
      var p = cellXY(k), ws = [hwAt(p.r, p.c), hwAt(p.r + 1, p.c), vwAt(p.r, p.c), vwAt(p.r, p.c + 1)], i;
      for (i = 0; i < ws.length; i++)
        if (ws[i] && ws[i].solid && !ws[i].flap) ws[i].lit = Math.max(ws[i].lit, lit * (0.75 + 0.25 * ((i * 7 + k) % 4) / 3));
    }
    function pulseAt(x, y, a, charge) {
      balls.push({ x: x, y: y, vx: Math.cos(a) * C.ballSpeed, vy: Math.sin(a) * C.ballSpeed,
                   life: C.ballLife * charge, alive: true });
    }
    function gates() {
      var i;
      for (i = 0; i < decoys.length; i++) drawGateAt(decoys[i].c, false, decoys[i]);
      drawGateAt(exitCol, true, null);
    }
    function sealAll() {
      var i;
      lockGate(exitCol);
      for (i = 0; i < decoys.length; i++) lockGate(decoys[i].c);
      lockFlare = 0.4;
    }
    // the fence on the mouth row: gap on door `at`, door `burnt` burned out
    function fence(at, burnt) {
      var i;
      surgeSeq = [];
      for (i = 0; i < MOUTHS; i++) if (i !== burnt) surgeSeq.push(i);
      if (burnt != null && mouths[burnt]) mouths[burnt].freed = true;
      surgeI = Math.max(0, surgeSeq.indexOf(at));
      surgeFlash = C.surgeFlash * 0.5;
      rollSurgeNoise();
      applySeal();
    }

    /* --- the pictures ---------------------------------------------------- */
    function boardPic() {
      return scene(520, 300, C.bands[0], function () {
        board({ cols: 8, rows: 4, cw: 60, ch: 46, x0: 20, y0: gateFloor() });
        phase = "reveal";
        grid(1); drawDoors(1); gates();
      });
    }
    function aimPic() {
      return scene(520, 300, null, function () {
        M = { cols: 12, rows: 1, cw: 40, ch: 40, x0: 20, y0: OY + 4, y1: OY + 48 };
        field = { left: 20, right: 500, top: OY + 4, bottom: OY + 292 };
        cannon = { x: 240, y: OY + 292 - C.cannonH };
        MOUTHS = 6; queue = Math.max(1, C.startBalls - 2); aimA = -1.22;
        drawDoors(1); drawAim(); drawCannon();
        pulseAt(108, OY + 132, -2.1, 0.55);         // an earlier shot, half spent
        drawBalls();
      });
    }
    function echoPic() {
      return scene(520, 300, null, function () {
        var n, i, p;
        board({ cols: 8, rows: 4, cw: 60, ch: 46, x0: 20, y0: gateFloor() });
        n = Math.max(2, Math.ceil(truePath.length * 0.7));
        for (i = 0; i < n; i++) strike(truePath[i], 0.34 + 0.66 * (i + 1) / n);
        p = cellXY(truePath[n - 1]);
        pulseAt(p.x - 8, p.y + 4, -1.0, 0.6);
        gates(); drawEchoes(); drawBalls();
      });
    }
    function escapePic() {
      return scene(520, 190, null, function () {
        var n, i, p;
        board({ cols: 8, rows: 2, cw: 60, ch: 46, x0: 20, y0: gateFloor() });
        n = truePath.length;
        for (i = Math.max(0, n - 4); i < n; i++) strike(truePath[i], 0.3 + 0.7 * (i - n + 5) / 4);
        gateFlare = 0.8;
        p = cellXY(truePath[n - 1]);
        pulseAt(p.x, M.y0 - 26, -Math.PI / 2, 0.8);
        drawEchoes(); gates(); drawBalls();
      });
    }
    function valvePic() {
      return scene(520, 300, null, function () {
        var i, a, b, w, got = [];
        board({ cols: 8, rows: 4, cw: 60, ch: 46, x0: 20, y0: gateFloor() });
        // the openings the true corridor climbs through, row by row
        for (i = 1; i < truePath.length && got.length < 2; i++) {
          a = cellXY(truePath[i - 1]); b = cellXY(truePath[i]);
          if (b.r < a.r && a.r < M.rows && a.r > 0) got.push(hwAt(a.r, a.c));
        }
        for (i = 0; i < got.length; i++) {
          w = got[i];
          if (!w) continue;
          w.solid = 1; w.flap = true; w.made = true; w.swing = i ? 0.3 : 1;
          valves.push(w);
        }
        grid(0.26); gates(); drawValves();
        w = valves[valves.length - 1];
        if (w) {
          pulseAt((w.x0 + w.x1) / 2 + 14, w.y0 - 34, -1.2, 0.7);
          strike(truePath[Math.min(truePath.length - 1, valves.length + 1)], 0.9);
        }
        drawEchoes(); drawBalls();
      });
    }
    function recapPic() {
      return scene(520, 312, null, function () {
        board({ cols: 8, rows: 4, cw: 60, ch: 46, x0: 20, y0: gateFloor() });
        phase = "recap"; recapT = C.recapSurge + C.recapSweep + C.recapTrace; gateFlare = 0.6;
        grid(0.95); drawDoors(0.95); gates(); drawTrueWay();
      });
    }
    function starsPic() {
      var src = CONFIG.shellArt && CONFIG.shellArt.star, box, i, im;
      if (!src) return null;
      box = document.createElement("div");
      box.className = "em-gstars";
      for (i = 0; i < 3; i++) { im = document.createElement("img"); im.src = src; im.alt = ""; box.appendChild(im); }
      return box;
    }
    // band 1: the board grows over the climb, two boards side by side
    function growPic() {
      return scene(520, 216, C.bands[0], function () {
        board({ cols: 6, rows: 3, cw: 32, ch: 30, x0: 22, y0: gateFloor() });
        grid(0.8); drawDoors(0.8); drawGateAt(exitCol, true, null);
        board({ cols: 8, rows: 4, cw: 31, ch: 30, x0: 250, y0: gateFloor() });
        grid(0.8); drawDoors(0.8); drawGateAt(exitCol, true, null);
      });
    }
    function decoyPic() {
      return scene(520, 260, C.bands[1], function () {
        board({ cols: 10, rows: 3, cw: 48, ch: 46, x0: 20, y0: gateFloor(), decoys: 2 });
        phase = "reveal"; clock = 0.3;
        grid(1); drawDoors(1); gates();
      });
    }
    function crystalPic() {
      return scene(520, 262, C.bands[2], function () {
        board({ cols: 8, rows: 2, cw: 60, ch: 46, x0: 20, y0: gateFloor(), bay: 300 });
        sealAll();
        grid(0.24); drawDoors(0.3); gates();
        drawGem(150, OY + 220, C.crystalR);
        pulseAt(214, OY + 248, Math.atan2(-28, -64), 0.85);
        drawBalls();
      });
    }
    function hiddenPic() {
      return scene(520, 300, C.bands[2], function () {
        board({ cols: 8, rows: 4, cw: 60, ch: 46, x0: 20, y0: gateFloor(), crystal: "maze" });
        sealAll();
        grid(0.3); drawDoors(0.3); gates();
        if (crystal) drawGem(crystal.x, crystal.y, crystal.r);
      });
    }
    function fencePic() {
      return scene(520, 210, C.bands[3], function () {
        var gx;
        board({ cols: 12, rows: 2, cw: 40, ch: 50, x0: 20, y0: 18, bay: 90 });
        fence(1, 4);
        gx = M.x0 + (surgeSeq[surgeI] * C.mouthW + 1) * M.cw;
        grid(0.22); drawSurge();
        pulseAt(gx + 10, M.y1 + 46, -1.3, 0.9);
        drawBalls();
      });
    }
    function surgePic() {
      return scene(520, 280, C.bands[4], function () {
        board({ cols: 10, rows: 3, cw: 48, ch: 46, x0: 20, y0: gateFloor(), bay: 40,
                decoys: 2, crystal: "maze" });
        sealAll();
        fence(1, null);
        grid(0.26); gates(); drawSurge();
        if (crystal) drawGem(crystal.x, crystal.y, crystal.r);
      });
    }

    var guide = {
      chapters: function () {
        var names = [Lang.t("Dark maze"), Lang.t("False exits"), Lang.t("Crystal lock"),
                     Lang.t("Live fence"), Lang.t("Full surge")];
        return [
          { key: "basics", label: Lang.t("The basics"), pages: [
            { id: "goal", title: Lang.t("Find the way out"), pic: boardPic, lines: [
              Lang.t("The maze is lit for a moment, then everything goes dark."),
              Lang.t("Only one door leads to the exit. The others end in dead ends.") ] },
            { id: "aim", title: Lang.t("Aim and fire"), pic: aimPic, lines: [
              Lang.t("Drag to aim, let go to fire a pulse."),
              Lang.t("The sight stops at a door. That is the door your pulse will take.") ] },
            { id: "echo", title: Lang.t("Echoes"), pic: echoPic, lines: [
              Lang.t("In the dark, a wall only shows where a pulse strikes it, then fades.") ] },
            { id: "valves", title: Lang.t("One-way valve"), pic: valvePic, lines: [
              Lang.t("When a pulse dies in the maze, the last opening it went through becomes a valve."),
              Lang.t("That valve lets pulses up, never back down.") ] },
            { id: "recap", title: Lang.t("The answer"), pic: recapPic, lines: [
              Lang.t("Out of pulses and still inside? The maze lights up one last time.") ] },
            { id: "score", title: Lang.t("Scoring"), pic: escapePic, rows: [
              [Lang.t("Each pulse left"), "+" + C.spareBonus] ], lines: [
              Lang.t("Pulses you have left pay the most. Getting out on the first shot gives the best score.") ] },
            { id: "stars", title: Lang.t("Stars"), pic: starsPic, rows: [
              [Lang.t("Out in 1 pulse"), "3"],
              [Lang.t("Out in 2 pulses"), "2"],
              [Lang.t("Out in 3 or more"), "1"],
              [Lang.t("No way out"), "0"] ], lines: [
              Lang.t("When the crystal hides in a dead end, each star allows one more pulse.") ] }
          ] },
          { key: "dark", label: names[0], pages: [
            { id: "dark", title: names[0], pic: growPic, lines: [
              Lang.t("Just the maze, its doors and one exit.") ] }
          ] },
          { key: "decoys", label: names[1], pages: [
            { id: "decoys", title: names[1], lv: 4, pic: decoyPic, lines: [
              Lang.t("A false exit looks exactly like the true one, but it swallows your pulse."),
              Lang.t("While the maze is lit, only the true exit sends out rings. Remember which one.") ] }
          ] },
          { key: "crystal", label: names[2], pages: [
            { id: "crystal", title: Lang.t("The crystal"), lv: 10, pic: crystalPic, lines: [
              Lang.t("Once the lights go out, a bar seals every exit. Break the crystal to lift it."),
              Lang.t("Below the doors, your pulse bounces off the crystal and can still reach a door.") ] },
            { id: "hidden", title: Lang.t("The hidden crystal"), lv: 11, pic: hiddenPic, lines: [
              Lang.t("The crystal can hide in a dead end of the maze."),
              Lang.t("Reaching the crystal costs a pulse of its own, so each star allows one more pulse.") ] }
          ] },
          { key: "fence", label: names[3], pages: [
            { id: "fence", title: names[3], lv: 18, pic: fencePic, lines: [
              Lang.t("The gap in the fence moves from door to door in a fixed order. Aim where it goes next."),
              Lang.t("A pulse that hits the fence is lost, but that door stays open for good.") ] }
          ] },
          { key: "surge", label: names[4], pages: [
            { id: "surge", title: names[4], lv: 23, pic: surgePic, lines: [
              Lang.t("Spot the true exit while the maze is lit, then break the crystal before you go for it.") ] }
          ] }
        ];
      }
    };

    function onResize() { geometry(); }

    /* --- THE LEVEL LAYER (web target) ------------------------------------
       The three-star finish: the web shell has already played the slow
       motion, and the round ends through the game's own result so the end
       screen keeps these stat rows. Ignored by the playable, which has no
       levels — see docs/LEVELS.md. */
    return { reset: reset, update: update, render: render,
             onDown: onDown, onMove: onMove, onUp: onUp, onResize: onResize,
             applyLevel: applyLevel, levelWon: finish, levelTally: levelTally,
             levelRules: levelRules, guide: guide };
  })();

